 	}
 	for _, c := range rec.Result().Cookies() {
 		if c.Name == authCookieName {
 			sid = c.Value
 		}
 	}
 	if sid == "" {
 		t.Fatal("Set-Cookie ai_sid не найден")
 	}
 	var out struct {
