+	// scope единицы работы, и точные моменты начала/конца вызова инструмента.
+	metrics *runmetrics.Registry
 	chat    *chat.Store
 	board   *board.Store
 	tok     *tokens.Store
 	ctx     context.Context
 	events  chan ProjectEvent // внутренняя шина событий проекта (для флашера и слушателей)
 	wg      sync.WaitGroup
 	stopped bool

