+  errors: number;
+  tokens_in: number;
+  tokens_out: number;
+}
+
+export interface MetricsStep {
+  scope: string;
+  step: string;
+  key: string;
+  value: number;
+}
+
+export interface ProjectMetrics {
+  project: string;
+  run_id: number;
+  since: string;
+  uptime_sec: number;
+  rounds: number;
+  tokens_in: number;
+  tokens_out: number;
+  tokens_total: number;
+  // Цены и стоимость: без заданных LLM_PRICE_IN/OUT price_* и cost равны 0,
+  // а cost_known == false — тогда интерфейс не показывает денежную оценку.
+  price_in: number;
+  price_out: number;
+  cost: number;
+  cost_known: boolean;
+  cost_in?: number;
+  cost_out?: number;
+  tps: number;
+  tool_calls: number;
+  tool_errors: number;
+  app_log_lines: number;
+  unpaired: number;
+  overflow: number;
+  tools: MetricsTool[];
+  scopes: MetricsScope[];
+  agents: MetricsAgent[];
+  steps: MetricsStep[];
+  // Итоги за всё время жизни проекта (Redis-счётчик tokens) в отличие от
+  // tokens_in/tokens_out, которые относятся к текущему запуску.
+  total_tokens_in: number;
+  total_tokens_out: number;
+  total_cost: number;
+  total_cost_known: boolean;
+  currency: string;
+  duration_buckets: number[];
+}

