@@ -1,341 +1,397 @@
 // Глобальные стили и CSS-переменные темы (оболочка App + <main className="panes">).
 // Компонемые стили живут рядом с ними (Components/*/styles.scss) и опираются
 // на эти переменные; тёмная тема придёт переопределением :root.

 :root {
   --bg: #f6f8fb;
   --card: #ffffff;
   --line: #e2e8f0;
   --ink: #1b2330;
   --muted: #8a94a6;
   --btn: #f1f5f9;
   --btn-hover: #e2e8f0;
   --col: #f4f6f9;
   --primary: #2563eb;
   --primary-hover: #1d4ed8;
   --err: #dc2626;
   --rem: #dc2626;
   --add: #16a34a;
   --mod: #2563eb;
   --st-todo: #64748b;
   --st-in-progress: #2563eb;
   --st-review: #b45309;
   --st-done: #15803d;
   --st-analysis: #7c3aed;
   --st-ready: #0891b2;
   --st-paused: #b45309;
   --mono: ui-monospace, SFMono-Regular, Menlo, "Courier New", monospace;
 }

 * {
   box-sizing: border-box;
 }

 html,
 body,
 #root {
   height: 100%;
   margin: 0;
 }

 body {
   font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
   background: var(--bg);
   color: var(--ink);
   font-size: 14px;
 }

 // Оболочка: заголовок + тулбар + основная область в столбик.
 .app {
   display: flex;
   flex-direction: column;
   height: 100%;
   min-height: 0;
 }

 // Верхний заголовок: пикер воркспейса + заглушка вкладок + действия справа.
 .top {
   display: flex;
   align-items: center;
   gap: 14px;
   padding: 10px 14px;
   background: var(--card);
   border-bottom: 1px solid var(--line);
 }

 .tabs {
   display: flex;
   align-items: center;
   gap: 4px;
 }

 .head-actions {
   margin-left: auto;
   display: flex;
   align-items: center;
   gap: 8px;

   .btn {
     font-size: 13px;
     padding: 6px 12px;
     border: 1px solid var(--line, #e2e8f0);
     border-radius: 8px;
     background: var(--btn, #f1f5f9);
     cursor: pointer;

     &:hover:not(:disabled) {
       background: var(--btn-hover, #e2e8f0);
     }
     &:disabled {
       opacity: 0.5;
       cursor: default;
     }

     &.danger {
       color: var(--err, #dc2626);
     }
   }
 }

 // Action-bar (общий для Чата и Логов): кластер компактных кнопок-действий
 // в шапке панели. Используется из Chatboard (головной .headbar) и Logboard
 // (головной .head).
 .abar {
   display: flex;
   align-items: center;
   gap: 6px;
   flex: 0 0 auto;

   .ab {
     display: inline-flex;
     align-items: center;
     gap: 6px;
     padding: 5px 10px;
     border: 1px solid var(--line, #e2e8f0);
     border-radius: 8px;
     background: var(--btn, #f1f5f9);
     color: var(--muted, #8a94a6);
     font-size: 12px;
     font-weight: 600;
     line-height: 1;
     cursor: pointer;

     svg {
       flex: 0 0 auto;
     }

     &:hover:not(:disabled) {
       background: var(--btn-hover, #e2e8f0);
       color: var(--ink, #1b2330);
     }

     &:disabled {
       opacity: 0.45;
       cursor: default;
     }
   }
 }

 // Строка статуса сессии под заголовком.
 .statusline {
   display: flex;
   align-items: center;
   gap: 10px;
   padding: 6px 14px;
   font-size: 13px;
   color: var(--muted, #8a94a6);
   background: var(--card, #fff);
   border-bottom: 1px solid var(--line, #e2e8f0);

   .detail {
     overflow: hidden;
     text-overflow: ellipsis;
     white-space: nowrap;
   }
 }

 // Баннер ошибки.
 .banner {
   display: flex;
   align-items: center;
   gap: 10px;
   padding: 8px 14px;
   font-size: 13px;

   &.err {
     color: var(--err, #dc2626);
     background: #fef2f2;
     border-bottom: 1px solid #fecaca;
   }

   button {
     margin-left: auto;
     border: none;
     background: transparent;
     color: inherit;
     font-size: 16px;
     cursor: pointer;
   }
 }

 // Основная область: чат и доска видны одновременно, пропорцию меняет
 // разделительная ширма (.splitter); при схлопывании остаётся тонкая полоска
 // слева (.chat-strip) или справа (.dash-strip). Состояния взаимоисключающие.
 .panes {
   flex: 1;
   min-height: 0;
   display: flex;

   // Во время перетаскивания ширмы запрещаем выделение текста.
   &.dragging {
     cursor: col-resize;
     user-select: none;

     .chat-pane,
     .dash-pane {
       pointer-events: none;
     }
   }
 }

 // Левая панель чата: ширина задаётся из JS (пропорция экрана при drag-ширме).
 .chat-pane {
   flex: 0 0 auto;
   min-width: 0;
   min-height: 0;
   display: flex;
   flex-direction: column;
   padding: 14px;
   overflow: hidden;
   background: var(--card);
 }

 .chat-strip {
   flex: 0 0 44px;
   min-height: 0;
   display: flex;
   border-right: 1px solid var(--line);
 }

 // Правая панель доски: занимает оставшуюся ширину.
 .dash-pane {
   flex: 1 1 auto;
   min-width: 0;
   min-height: 0;
   display: flex;
   flex-direction: column;
   padding: 14px;
   overflow: auto;
 }

 // Статусная колонка доски справа (аналог .chat-strip, зеркально).
 .dash-strip {
   flex: 0 0 44px;
   min-height: 0;
   display: flex;
   border-left: 1px solid var(--line);
   background: var(--card);
 }

 // Разделительная ширма: перетаскивается, меняет пропорцию чат/доска.
 .splitter {
   flex: 0 0 10px;
   min-height: 0;
   position: relative;
   z-index: 5;
   cursor: col-resize;
   touch-action: none;
   background: transparent;

   // Вертикальная линия-граница между панелями.
   &::before {
     content: "";
     position: absolute;
     top: 0;
     bottom: 0;
     left: 50%;
     width: 1px;
     transform: translateX(-50%);
     background: var(--line);
     transition: background 0.15s ease, width 0.15s ease;
   }

   &:hover::before,
   &.active::before {
     width: 3px;
     background: var(--primary, #2563eb);
   }
 }

 // Плавающая кнопка открытия Logboard (справа внизу).
 .fabs {
   position: fixed;
   right: 18px;
   bottom: 18px;
   z-index: 40;
   display: flex;
   gap: 10px;
 }

 .fab {
   padding: 10px 18px;
   border: none;
   border-radius: 999px;
   background: var(--primary, #2563eb);
   color: #fff;
   font-size: 13px;
   font-weight: 600;
   cursor: pointer;
   box-shadow: 0 6px 18px rgb(0 0 0 / 0.18);

   &:hover {
     background: var(--primary-hover, #1d4ed8);
   }
 }

 // Diffboard-шторка: выезжает снизу, 90% высоты и вся ширина экрана.
 .diff-drawer {
   position: fixed;
   left: 0;
   right: 0;
   bottom: 0;
   z-index: 120;
   height: 90vh;
   display: flex;
   flex-direction: column;
   padding: 14px 16px;
   background: var(--bg, #f6f8fb);
   border-top: 1px solid var(--line, #e2e8f0);
   box-shadow: 0 -8px 30px rgb(0 0 0 / 0.14);
   transform: translateY(100%);
   visibility: hidden;
   transition: transform 0.25s ease, visibility 0.25s;

   &.open {
     transform: translateY(0);
     visibility: visible;
   }

   .diffboard,
   .logboard {
     flex: 1;
     min-height: 0;
   }
 }

 @media (max-width: 640px) {
   .diff-drawer {
     height: 95dvh;
     padding: 10px;
   }
 }

+// Metricsboard-шторка (Ф-1): та же геометрия, что у дифф-шторки, но с
