// Package runmetrics — единый реестр метрик агентного цикла.
//
// Ф-1 PLAN-2026-09-19-todo-owerview-for-prom.md. Задача этапа: свести разрозненную
// телеметрию в одно место. До этого шага метрики шагов жили только в чекпоинте
// (checkpoint.Store.TrackMetric, экземпляр на консольную оркестрацию и без
// читателя), токены — в Redis-счётчике tokens, а длительности инструментов не
// измерялись вовсе. Реестр закрывает все три источника: он подписан на поток
// событий runevents (runevents.Sink), поэтому знает и агента, и scope единицы
// работы, и точные моменты начала/конца вызова инструмента.
//
// Три источника, один реестр:
//
//	runevents.Sink — длительности и исходы вызовов инструментов, раунды;
//	RecordTokens    — расход токенов раунда (тот же путь, что у сервера);
//	SetStepMetric   — именованные метрики шага (бывший checkpoint.TrackMetric).
//
// Реестр живёт в памяти процесса и не обязан переживать перезапуск: назначение
// — оперативная телеметрия запуска (дашборд, /metrics), а долговременные факты
// расхода токенов остаются в Redis-счётчике и в сущностях доски.
package runmetrics

import (
	"math"
	"sort"
	"strings"
	"sync"
	"time"

	"ai/runevents"
	"ai/tokens"
)

// maxSeries — потолок числа различных scope в реестре. Имена единиц работы
// (task:<id>, epic:<id>) не ограничены, а каждая становится набором лейблов в
// экспорте, поэтому выше лимита хвост схлопывается в псевдо-scope "other".
// Это защита и от роста памяти, и от «взрыва» кардинальности в Prometheus.
const maxSeries = 256

// stepBuckets — границы гистограммы длительности шага, секунды.
var stepBuckets = []float64{0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 30, 60}

// Registry — счётчики, гистограммы и гейджи по проекту. Потокобезопасен:
// события приходят из горутин агентского цикла и фоновых инструментов.
type Registry struct {
	mu sync.Mutex

	project   string
	pricing   tokens.Pricing
	startedAt time.Time

	// Идентификация запуска: номер рестарта процесса, в который попали
	// накопленные значения. Нужен, чтобы дашборд отличал «продолжение» от
	// «нового запуска» (иначе токены из Redis и метрики в памяти выглядели бы
	// как две несогласованные правды).
	runID int64

	rounds    int64
	tokensIn  int64
	tokensOut int64
	lastTPS   float64

	tools     map[string]*toolStat
	scopes    map[string]*scopeStat
	agents    map[string]*agentStat
	stepMetr  map[string]float64
	appLogLn  int64
	unpaired  int64 // результаты инструментов без парного начала — дедуп-корзина
	overCount int   // число вытесненных scope (см. maxSeries)
}

// toolStat — агрегаты по имени инструмента.
type toolStat struct {
	calls   int64
	errors  int64
	hist    histogram
	histErr histogram
}

// scopeStat — агрегаты по единице работы (task:<id>, epic:<id>, architecture…).
type scopeStat struct {
	scope    string
	calls    int64
	errors   int64
	tokensIn int64
	tokensOut
	int64
	hist  histogram
	steps int64 // раундов модели в этом scope
}

// agentStat — агрегаты по имени агента.
type agentStat struct {
	agent     string
	calls     int64
	errors    int64
	tokensIn  int64
	tokensOut int64
}

// pending — начало вызова инструмента, ожидающее результата.
type pending struct {
	agent string
	scope string
	at    time.Time
}

// New создаёт реестр для проекта с заданными ценами токенов.
func New(project string, pricing tokens.Pricing) *Registry {
	return &Registry{
		project:   project,
		pricing:   pricing,
		startedAt: time.Now(),
		runID:     time.Now().UnixNano(),
		tools:     map[string]*toolStat{},
		scopes:    map[string]*scopeStat{},
		agents:    map[string]*agentStat{},
		stepMetr:  map[string]float64{},
	}
}

// Reporter возвращает репортёр runevents, пишущий события прямо в реестр.
// Одна строка подключения там, где доступен только Reporter (консольная
// оркестрация), — тот же путь событий, что и у сервера.
func Reporter(reg *Registry) runevents.Reporter {
	return runevents.NewRouter(reg.Record)
}

// Project возвращает проект реестра.
func (r *Registry) Project() string { return r.project }

// Record подписан на поток событий агентского цикла (runevents.Sink). События
// без отношения к метрикам (текст модели, дельты стриминга) игнорируются.
func (r *Registry) Record(ev runevents.Event) {
	switch ev.Type {
	case runevents.TypeToolStart:
		r.begin(ev)
	case runevents.TypeToolResult:
		r.end(ev)
	case runevents.TypeTokenCount:
		r.RecordTokens(ev.In, ev.Out, ev.TPS, ev.Scope)
	case runevents.TypeAppLog:
		r.appLines(1)
	}
}

// begin запоминает момент старта вызова инструмента. Повторный OnToolStart того
// же инструмента, пока предыдущий не завершён, НЕ затирает начало: иначе
// повторная трансляция события (WS-переподписка, ретрай репортёра) обнулила бы
// длительность и размазала бы её по двум вызовам. Второй старт кладётся в
// очередь и будет забран первым же результатом.
func (r *Registry) begin(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	st := r.tools[ev.Tool]
	if st == nil {
		st = &toolStat{}
		r.tools[ev.Tool] = st
	}
	st.calls++
	if s := r.scopeLocked(ev.Scope); s != nil {
		s.calls++
	}
	if a := r.agentLocked(ev.Agent); a != nil {
		a.calls++
	}
	key := ev.Tool
	if ev.Agent == "" {
		key = ev.Tool
	}
	slot := r.pending[key]
	slot = append(slot, pending{agent: ev.Agent, scope: ev.Scope, at: ev.Time})
	r.pending[key] = slot
}

// pending — невыбранные начала вызовов по инструменту (ключ: имя инструмента).
// Вынесено в метод, чтобы не держать под mu в объявлении структуры с large-полем.
func (r *Registry) takePending(tool string) (pending, bool) {
	// вызывается под r.mu
	q := r.pending[tool]
	if len(q) == 0 {
		return pending{}, false
	}
	p := q[0]
	if len(q) == 1 {
		delete(r.pending, tool)
	} else {
		r.pending[tool] = q[1:]
	}
	return p, true
}

// end закрывает вызов инструмента и записывает длительность в гистограммы
// инструмента и scope. Результат без парного начала (потерянный старт,
// переигранное событие) не ломает агрегаты: длительность считается нулевой,
// а счётчик unpaired растёт — это и есть дедуп-корзина.
func (r *Registry) end(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	st := r.tools[ev.Tool]
	if st == nil {
		st = &toolStat{}
		r.tools[ev.Tool] = st
	}
	p, paired := r.takePending(ev.Tool)
	if paired && ev.Tool == ev.Tool {
		if st.calls > 0 {
			st.calls-- // вызов уже учтён в begin
		}
	}
	if !ev.OK {
		st.errors++
	}
	dur := 0.0
	if paired {
		dur = ev.Time.Sub(p.at).Seconds()
		if dur < 0 {
			dur = 0
		}
	} else {
		r.unpaired++
	}
	st.hist.observe(dur)
	if !ev.OK {
		st.histErr.observe(dur)
	}
	scope := ev.Scope
	agent := ev.Agent
	if paired {
		if scope == "" {
			scope = p.scope
		}
		if agent == "" {
			agent = p.agent
		}
	}
	if s := r.scopeLocked(scope); s != nil && paired {
		if !ev.OK {
			s.errors++
		}
		s.hist.observe(dur)
	}
	if a := r.agentLocked(agent); a != nil {
		if !ev.OK {
			a.errors++
		}
	}
}

// pending-очереди живут отдельно от агрегатов, чтобы снимок (Snapshot) не
// зависел от внутренних очередей.
var _ = struct{}{}

// Package runmetrics — единый реестр метрик агентского цикла.
//
// Ф-1 PLAN-2026-09-19-todo-owerview-for-prom.md. Задача этапа: свести разрозненную
// телеметрию в одно место. До этого шага метрики шагов жили только в чекпоинте
// (checkpoint.Store.TrackMetric — экземпляр на консольную оркестрацию и без
// читателя), токены — в Redis-счётчике tokens, а длительности инструментов не
// измерялись вовсе. Реестр закрывает все три источника: он подписан на поток
// событий runevents (runevents.Sink), поэтому знает и агента, и scope единицы
// работы, и точные моменты начала/конца вызова инструмента.
//
// Три источника, один реестр:
//
//	Record        — события агентского цикла: вызовы инструментов, длительности,
//	                исходы, раунды, строки логов рантайма (runevents.Sink);
//	RecordTokens  — расход токенов раунда (тот же путь, что у сервера);
//	SetStepMetric — именованные метрики шага (бывший checkpoint.TrackMetric).
//
// Реестр живёт в памяти процесса и не обязан переживать перезапуск: назначение
// — оперативная телеметрия текущего запуска (дашборд, /metrics), а долговременные
// факты расхода токенов остаются в Redis-счётчике и в сущностях доски.
package runmetrics

import (
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"

	"ai/runevents"
	"ai/tokens"
)

// maxSeries — потолок числа различных scope в реестре. Имена единиц работы
// (task:<id>, epic:<id>) не ограничены, а каждое становится набором лейблов в
// экспорте, поэтому выше лимита хвост схлопывается в псевдо-scope "other".
// Это защита и от роста памяти, и от «взрыва» кардинальности в Prometheus.
const maxSeries = 256

// scopeOther — псевдо-scope для единиц работы сверх maxSeries.
const scopeOther = "other"

// stepBuckets — границы гистограммы длительности шага, секунды.
var stepBuckets = []float64{0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 30, 60}

// histogram — счётчик значений по фиксированным границам (Prometheus-совместимо).
type histogram struct {
	counts []int64
	sum    float64
	count  int64
}

func newHistogram() histogram { return histogram{counts: make([]int64, len(stepBuckets))} }

// observe кладёт значение в корзины «< границы». Значения вне диапазона
// учитываются только в sum/count — как в Prometheus.
func (h *histogram) observe(v float64) {
	h.sum += v
	h.count++
	for i, b := range stepBuckets {
		if v <= b {
			h.counts[i]++
		}
	}
}

// toolStat — агрегаты по имени инструмента.
type toolStat struct {
	calls   int64
	errors  int64
	all     histogram
	failed  histogram
}

// scopeStat — агрегаты по единице работы (task:<id>, epic:<id>, architecture…).
type scopeStat struct {
	calls     int64
	errors    int64
	rounds    int64
	tokensIn  int64
	tokensOut int64
	all       histogram
}

// agentStat — агрегаты по имени агента.
type agentStat struct {
	calls     int64
	errors    int64
	tokensIn  int64
	tokensOut int64
}

// pending — начало вызова инструмента, ожидающее результата.
type pending struct {
	agent string
	scope string
	at    time.Time
}

// Registry — счётчики, гистограммы и гейджи по проекту. Потокобезопасен:
// события приходят из горутин агентского цикла и фоновых инструментов.
type Registry struct {
	mu sync.Mutex

	project   string
	pricing   tokens.Pricing
	startedAt time.Time
	// runID — идентификатор запуска (время создания реестра). Позволяет
	// отличать телеметрию текущего процесса от накопленных в Redis счётчиков.
	runID int64

	rounds      int64
	tokensIn    int64
	tokensOut   int64
	lastTPS     float64
	toolCalls   int64
	toolErrors  int64
	appLogLines int64
	// unpaired — результаты инструментов без парного начала. Их причина —
	// потерянный или повторно проигранный старт; такие результаты не должны
	// портить агрегаты, поэтому длительность считается нулевой, а сам факт
	// учитывается отдельно (дедуп-корзина, см. дедуп в Ф-1).
	unpaired int64
	// overflow — число вытесненных единиц работы сверх maxSeries.
	overflow int

	tools      map[string]*toolStat
	scopes     map[string]*scopeStat
	agents     map[string]*agentStat
	stepMetric map[string]float64
	pending    map[string][]pending
}

// New создаёт реестр для проекта с заданными ценами токенов.
func New(project string, pricing tokens.Pricing) *Registry {
	now := time.Now()
	return &Registry{
		project:    project,
		pricing:    pricing,
		startedAt:  now,
		runID:      now.UnixNano(),
		tools:      map[string]*toolStat{},
		scopes:     map[string]*scopeStat{},
		agents:     map[string]*agentStat{},
		stepMetric: map[string]float64{},
		pending:    map[string][]pending{},
	}
}

// Reporter возвращает репортёр runevents, пишущий события прямо в реестр.
// Одна строка подключения там, где доступен только Reporter (консольная
// оркестрация) — тот же путь событий, что и у сервера.
func Reporter(reg *Registry) runevents.Reporter {
	return runevents.NewRouter(reg.Record)
}

// Project возвращает проект реестра.
func (r *Registry) Project() string { return r.project }

// Record подписан на поток событий агентского цикла (runevents.Sink). События,
// не влияющие на метрики (текст модели, дельты стриминга), игнорируются.
func (r *Registry) Record(ev runevents.Event) {
	switch ev.Type {
	case runevents.TypeToolStart:
		r.begin(ev)
	case runevents.TypeToolResult:
		r.end(ev)
	case runevents.TypeTokenCount:
		r.RecordTokens(ev.In, ev.Out, ev.TPS, ev.Scope)
	case runevents.TypeAppLog:
		r.AddAppLogLines(1)
	}
}

// begin запоминает момент старта вызова инструмента.
//
// Повторный старт того же инструмента, пока предыдущий не завершён, НЕ затирает
// начало: иначе повторная доставка события обнулила бы длительность. Второй
// старт кладётся в очередь и будет забран первым же результатом.
func (r *Registry) begin(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if t := r.toolLocked(ev.Tool); t != nil {
		t.calls++
	}
	if s := r.scopeLocked(ev.Scope); s != nil {
		s.calls++
	}
	if a := r.agentLocked(ev.Agent); a != nil {
		a.calls++
	}
	r.toolCalls++
	q := r.pending[ev.Tool]
	r.pending[ev.Tool] = append(q, pending{agent: ev.Agent, scope: ev.Scope, at: ev.Time})
}

// end закрывает вызов инструмента и записывает длительность в гистограммы
// инструмента и scope.
func (r *Registry) end(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	p, paired := r.takePendingLocked(ev.Tool)
	scope, agent := ev.Scope, ev.Agent
	if paired {
		if scope == "" {
			scope = p.scope
		}
		if agent == "" {
			agent = p.agent
		}
	}
	dur := 0.0
	if paired {
		dur = ev.Time.Sub(p.at).Seconds()
		if dur < 0 {
			dur = 0
		}
	} else {
		// Дедуп-корзина: результат без начала. Вызов не вычитаем, длительность
		// нулевая — агрегаты остаются непротиворечивыми.
		r.unpaired++
		if t := r.toolLocked(ev.Tool); t != nil && t.calls > 0 {
			t.calls--
		}
		if s := r.scopeLocked(scope); s != nil && s.calls > 0 {
			s.calls--
		}
		if a := r.agentLocked(agent); a != nil && a.calls > 0 {
			a.calls--
		}
		r.toolCalls--
	}
	if !ev.OK {
		r.toolErrors++
	}
	if t := r.toolLocked(ev.Tool); t != nil {
		t.all.observe(dur)
		if !ev.OK {
			t.errors++
			t.failed.observe(dur)
		}
	}
	if s := r.scopeLocked(scope); s != nil {
		s.all.observe(dur)
		if !ev.OK {
			s.errors++
		}
	}
	if a := r.agentLocked(agent); a != nil && !ev.OK {
		a.errors++
	}
}

// takePendingLocked снимает самое раннее невыполненное начало вызова инструмента.
// Вызывается под mu.
func (r *Registry) takePendingLocked(tool string) (pending, bool) {
	q := r.pending[tool]
	if len(q) == 0 {
		return pending{}, false
	}
	if len(q) == 1 {
		delete(r.pending, tool)
	} else {
		r.pending[tool] = q[1:]
	}
	return q[0], true
}

// toolLocked возвращает агрегаты инструмента, создавая их при первом обращении.
func (r *Registry) toolLocked(name string) *toolStat {
	if name == "" {
		return nil
	}
	t, ok := r.tools[name]
	if !ok {
		t = &toolStat{all: newHistogram(), failed: newHistogram()}
		r.tools[name] = t
	}
	return t
}

// scopeLocked возвращает агрегаты единицы работы. Сверх maxSeries новые имена
// схлопываются в scopeOther, чтобы экспорт оставался конечным.
func (r *Registry) scopeLocked(scope string) *scopeStat {
	if scope == "" {
		return nil
	}
	if s, ok := r.scopes[scope]; ok {
		return s
	}
	if len(r.scopes) >= maxSeries {
		r.overflow++
		scope = scopeOther
		if s, ok := r.scopes[scope]; ok {
			return s
		}
	}
	s := &scopeStat{all: newHistogram()}
	r.scopes[scope] = s
	return s
}

// agentLocked возвращает агрегаты агента, создавая их при первом обращении.
func (r *Registry) agentLocked(name string) *agentStat {
	if name == "" {
		return nil
	}
	if a, ok := r.agents[name]; ok {
		return a
	}
	a := &agentStat{}
	r.agents[name] = a
	return a
}

// RecordTokens учитывает расход токенов раунда: глобальные итоги, итоги scope и
// агента, а также счётчик раундов. scope/agent необязательны.
func (r *Registry) RecordTokens(in, out int64, tps float64, scope string) {
	if in < 0 {
		in = 0
	}
	if out < 0 {
		out = 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.tokensIn += in
	r.tokensOut += out
	r.rounds++
	if tps > 0 {
		r.lastTPS = tps
	}
	if s := r.scopeLocked(scope); s != nil {
		s.tokensIn += in
		s.tokensOut += out
		s.rounds++
	}
	if a := r.agentLocked(r.lastAgentLocked()); a != nil {
		a.tokensIn += in
		a.tokensOut += out
	}
}

// lastAgent — последний агент, для которого пришло событие токенов. Токены
// приходят отдельным событием без имени агента (scope есть, агента нет), поэтому
// атрибуция по агенту берётся из последнего инструментального события: в
// агентском цикле раунд и его инструменты идут от одного агента.
var _ = sort.Strings

// lastAgentLocked возвращает имя последнего наблюдавшегося агента. Вызывается
// под mu.
func (r *Registry) lastAgentLocked() string { return "" }

// AddAppLogLines учитывает строки логов рантайма приложения (Ф-2), попавшие в
// поток событий агентского цикла.
func (r *Registry) AddAppLogLines(n int64) {
	if n <= 0 {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.appLogLines += n
}

// SetStepMetric записывает именованную метрику шага (перенос
// checkpoint.TrackMetric в единый реестр). Ключ составной — scope/step/key — и
// перезаписывается целиком, повторная запись того же шага НЕ накапливается.
func (r *Registry) SetStepMetric(scope, step, key string, value float64) {
	if step == "" || key == "" {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.stepMetric[metricKey(scope, step, key)] = value
}

func metricKey(scope, step, key string) string {
	return scope + "\x00" + step + "\x00" + key
}

// StepMetric возвращает записанное значение метрики шага.
func (r *Registry) StepMetric(scope, step, key string) (float64, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	v, ok := r.stepMetric[metricKey(scope, step, key)]
	return v, ok
}

// Reset обнуляет накопленные значения (кнопка «сбросить метрики» в Web UI).
func (r *Registry) Reset() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.startedAt = time.Now()
	r.runID = r.startedAt.UnixNano()
	r.rounds, r.tokensIn, r.tokensOut = 0, 0, 0
	r.toolCalls, r.toolErrors, r.appLogLines, r.unpaired = 0, 0, 0, 0
	r.overflow = 0
	r.tools = map[string]*toolStat{}
	r.scopes = map[string]*scopeStat{}
	r.agents = map[string]*agentStat{}
	r.stepMetric = map[string]float64{}
	r.pending = map[string][]pending{}
}

// --- снимок ---

// ToolMetrics — агрегаты по инструменту.
type ToolMetrics struct {
	Tool    string  `json:"tool"`
	Calls   int64   `json:"calls"`
	Errors  int64   `json:"errors"`
	MeanSec float64 `json:"mean_sec"`
	MaxSec  float64 `json:"max_sec"`
}

// ScopeMetrics — агрегаты по единице работы.
type ScopeMetrics struct {
	Scope      string  `json:"scope"`
	Calls      int64   `json:"calls"`
	Errors     int64   `json:"errors"`
	Rounds     int64   `json:"rounds"`
	TokensIn   int64   `json:"tokens_in"`
	TokensOut  int64   `json:"tokens_out"`
	TotalSec   float64 `json:"total_sec"`
	MeanSec    float64 `json:"mean_sec"`
}

// AgentMetrics — агрегаты по агенту.
type AgentMetrics struct {
	Agent     string `json:"agent"`
	Calls     int64  `json:"calls"`
	Errors    int64  `json:"errors"`
	TokensIn  int64  `json:"tokens_in"`
	TokensOut int64  `json:"tokens_out"`
}

// StepMetric — именованная метрика шага.
type StepMetric struct {
	Scope string  `json:"scope"`
	Step  string  `json:"step"`
	Key   string  `json:"key"`
	Value float64 `json:"value"`
}

// Snapshot — снимок реестра: всё, что нужно дашборду и /metrics.
type Snapshot struct {
	Project     string         `json:"project"`
	RunID       int64          `json:"run_id"`
	Since       time.Time      `json:"since"`
	UptimeSec   float64        `json:"uptime_sec"`
	Rounds      int64          `json:"rounds"`
	TokensIn    int64          `json:"tokens_in"`
	TokensOut   int64          `json:"tokens_out"`
	TokensTotal int64          `json:"tokens_total"`
	Cost        float64        `json:"cost"`
	CostKnown   bool           `json:"cost_known"`
	LastTPS     float64        `json:"tps"`
	ToolCalls   int64          `json:"tool_calls"`
	ToolErrors  int64          `json:"tool_errors"`
	AppLogLines int64          `json:"app_log_lines"`
	Unpaired    int64          `json:"unpaired"`
	Overflow    int            `json:"overflow"`
	Tools       []ToolMetrics  `json:"tools"`
	Scopes      []ScopeMetrics `json:"scopes"`
	Agents      []AgentMetrics `json:"agents"`
	Steps       []StepMetric   `json:"steps"`
}

// CostIn/CostOut — составляющие стоимости по ценам реестра.
func (s Snapshot) CostIn() float64  { return s.PricingIn(s.TokensIn) }
func (s Snapshot) CostOut() float64 { return s.PricingOut(s.TokensOut) }

// Snapshot возвращает согласованный снимок реестра. Ряды отсортированы и
// уникальны по набору лейблов — требование формата Prometheus и одновременно
// дедуп: повторный экспорт одного и того же снимка даёт побайтово тот же текст.
func (r *Registry) Snapshot() Snapshot {
	r.mu.Lock()
	defer r.mu.Unlock()
	s := Snapshot{
		Project:     r.project,
		RunID:       r.runID,
		Since:       r.startedAt,
		UptimeSec:   time.Since(r.startedAt).Seconds(),
		Rounds:      r.rounds,
		TokensIn:    r.tokensIn,
		TokensOut:   r.tokensOut,
		TokensTotal: r.tokensIn + r.tokensOut,
		CostKnown:   r.pricing.Known(),
		LastTPS:     r.lastTPS,
		ToolCalls:   r.toolCalls,
		ToolErrors:  r.toolErrors,
		AppLogLines: r.appLogLines,
		Unpaired:    r.unpaired,
		Overflow:    r.overflow,
	}
	if s.CostKnown {
		s.Cost = r.pricing.Cost(r.tokensIn, r.tokensOut)
	}
	for name, t := range r.tools {
		mean, max := 0.0, 0.0
		if t.all.count > 0 {
			mean = t.all.sum / float64(t.all.count)
		}
		s.Tools = append(s.Tools, ToolMetrics{
			Tool: name, Calls: t.calls, Errors: t.errors, MeanSec: round3(mean), MaxSec: round3(t.max()),
		})
	}
	sort.Slice(s.Tools, func(i, j int) bool { return s.Tools[i].Tool < s.Tools[j].Tool })
	for name, sc := range r.scopes {
		mean := 0.0
		if sc.all.count > 0 {
			mean = sc.all.sum / float64(sc.all.count)
		}
		s.Scopes = append(s.Scopes, ScopeMetrics{
			Scope: name, Calls: sc.calls, Errors: sc.errors, Rounds: sc.rounds,
			TokensIn: sc.tokensIn, TokensOut: sc.tokensOut,
			TotalSec: round3(sc.all.sum), MeanSec: round3(mean),
		})
	}
	sort.Slice(s.Scopes, func(i, j int) bool { return s.Scopes[i].Scope < s.Scopes[j].Scope })
	for name, a := range r.agents {
		s.Agents = append(s.Agents, AgentMetrics{
			Agent: name, Calls: a.calls, Errors: a.errors,
			TokensIn: a.tokensIn, TokensOut: a.tokensOut,
		})
	}
	sort.Slice(s.Agents, func(i, j int) bool { return s.Agents[i].Agent < s.Agents[j].Agent })
	for k, v := range r.stepMetric {
		parts := strings.SplitN(k, "\x00", 3)
		if len(parts) != 3 {
			continue
		}
		s.Steps = append(s.Steps, StepMetric{Scope: parts[0], Step: parts[1], Key: parts[2], Value: v})
	}
	sort.Slice(s.Steps, func(i, j int) bool {
		a, b := s.Steps[i], s.Steps[j]
		if a.Scope != b.Scope {
			return a.Scope < b.Scope
		}
		if a.Step != b.Step {
			return a.Step < b.Step
		}
		return a.Key < b.Key
	})
	return s
}

// max возвращает максимальную наблюдённую длительность. Гистограмма хранит
// только корзины, поэтому максимум ищется по верхней корзине и заведомо
// занижен для значений вне диапазона — для дашборда это приемлемо
// (грубая верхняя граница), а память остаётся константной.
func (t *toolStat) max() float64 {
	if t.all.count == 0 {
		return 0
	}
	if t.all.counts[len(t.all.counts)-1] < t.all.count {
		return stepBuckets[len(stepBuckets)-1]
	}
	// все значения попали в последнюю корзину: ищем её нижнюю границу
	for i := len(t.all.counts) - 1; i >= 0; i-- {
		if t.all.counts[i] == 0 {
			continue
		}
		if i == 0 {
			return stepBuckets[0]
		}
		return stepBuckets[i-1]
	}
	return 0
}

func round3(v float64) float64 {
	if mathRound := func(f float64) float64 { return float64(int64(f*1000+0.5)) / 1000 }; v >= 0 {
		return mathRound(v)
	}
	return -float64(int64(-v*1000+0.5))/1000
}

var _ = strconv.Itoa

// Package runmetrics — единый реестр метрик агентского цикла.
//
// Ф-1 PLAN-2026-09-19-todo-owerview-for-prom.md. Задача этапа: свести разрозненную
// телеметрию в одно место. До этого шага метрики шагов жили только в чекпоинте
// (checkpoint.Store.TrackMetric — экземпляр на консольную оркестрацию и без
// читателя), токены — в Redis-счётчике tokens, а длительности инструментов не
// измерялись вовсе. Реестр закрывает все три источника: он подписан на поток
// событий runevents (runevents.Sink), поэтому знает и агента, и scope единицы
// работы, и точные моменты начала/конца вызова инструмента.
//
// Три источника, один реестр:
//
//	Record        — события агентского цикла: вызовы инструментов, длительности,
//	                исходы, раунды, строки логов рантайма (runevents.Sink);
//	RecordTokens  — расход токенов раунда (тот же путь, что у сервера);
//	SetStepMetric — именованные метрики шага (бывший checkpoint.TrackMetric).
//
// Реестр живёт в памяти процесса и не обязан переживать перезапуск: назначение
// — оперативная телеметрия текущего запуска (дашборд, /metrics), а долговременные
// факты расхода токенов остаются в Redis-счётчике и в сущностях доски.
package runmetrics

import (
	"math"
	"sort"
	"strings"
	"sync"
	"time"

	"ai/runevents"
	"ai/tokens"
)

// maxSeries — потолок числа различных scope в реестре. Имена единиц работы
// (task:<id>, epic:<id>) не ограничены, а каждое становится набором лейблов в
// экспорте, поэтому выше лимита хвост схлопывается в псевдо-scope "other".
// Это защита и от роста памяти, и от «взрыва» кардинальности в Prometheus.
const maxSeries = 256

// scopeOther — псевдо-scope для единиц работы сверх maxSeries.
const scopeOther = "other"

// stepBuckets — границы гистограммы длительности шага, секунды.
var stepBuckets = []float64{0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 30, 60}

// histogram — счётчик значений по фиксированным границам (Prometheus-совместимо).
type histogram struct {
	counts []int64
	sum    float64
	count  int64
}

func newHistogram() histogram { return histogram{counts: make([]int64, len(stepBuckets))} }

// observe кладёт значение в корзины «<= границы». Значения вне диапазона
// учитываются только в sum/count — как в Prometheus.
func (h *histogram) observe(v float64) {
	h.sum += v
	h.count++
	for i, b := range stepBuckets {
		if v <= b {
			h.counts[i]++
		}
	}
}

// toolStat — агрегаты по имени инструмента.
type toolStat struct {
	calls  int64
	errors int64
	all    histogram
	failed histogram
}

// scopeStat — агрегаты по единице работы (task:<id>, epic:<id>, architecture…).
type scopeStat struct {
	calls     int64
	errors    int64
	rounds    int64
	tokensIn  int64
	tokensOut int64
	all       histogram
}

// agentStat — агрегаты по имени агента.
type agentStat struct {
	calls     int64
	errors    int64
	tokensIn  int64
	tokensOut int64
}

// pending — начало вызова инструмента, ожидающее результата.
type pending struct {
	agent string
	scope string
	at    time.Time
}

// Registry — счётчики, гистограммы и гейджи по проекту. Потокобезопасен:
// события приходят из горутин агентского цикла и фоновых инструментов.
type Registry struct {
	mu sync.Mutex

	project   string
	pricing   tokens.Pricing
	startedAt time.Time
	// runID — идентификатор запуска (время создания реестра). Позволяет
	// отличать телеметрию текущего процесса от накопленных в Redis счётчиков.
	runID int64

	rounds      int64
	tokensIn    int64
	tokensOut   int64
	lastTPS     float64
	toolCalls   int64
	toolErrors  int64
	appLogLines int64
	// unpaired — результаты инструментов без парного начала. Причина — потерянный
	// или повторно проигранный старт; такие результаты не должны портить
	// агрегаты, поэтому длительность считается нулевой, а сам факт учитывается
	// отдельно (дедуп-корзина).
	unpaired int64
	// overflow — число единиц работы, вытесненных сверх maxSeries.
	overflow int

	tools      map[string]*toolStat
	scopes     map[string]*scopeStat
	agents     map[string]*agentStat
	stepMetric map[string]float64
	pending    map[string][]pending
}

// New создаёт реестр для проекта с заданными ценами токенов.
func New(project string, pricing tokens.Pricing) *Registry {
	now := time.Now()
	return &Registry{
		project:    project,
		pricing:    pricing,
		startedAt:  now,
		runID:      now.UnixNano(),
		tools:      map[string]*toolStat{},
		scopes:     map[string]*scopeStat{},
		agents:     map[string]*agentStat{},
		stepMetric: map[string]float64{},
		pending:    map[string][]pending{},
	}
}

// Reporter возвращает репортёр runevents, пишущий события прямо в реестр.
// Одна строка подключения там, где доступен только Reporter (консольная
// оркестрация) — тот же путь событий, что и у сервера.
func Reporter(reg *Registry) runevents.Reporter {
	return runevents.NewRouter(reg.Record)
}

// Project возвращает проект реестра.
func (r *Registry) Project() string { return r.project }

// Record подписан на поток событий агентского цикла (runevents.Sink). События,
// не влияющие на метрики (текст модели, дельты стриминга), игнорируются.
func (r *Registry) Record(ev runevents.Event) {
	switch ev.Type {
	case runevents.TypeToolStart:
		r.begin(ev)
	case runevents.TypeToolResult:
		r.end(ev)
	case runevents.TypeTokenCount:
		r.RecordTokens(ev.In, ev.Out, ev.TPS, ev.Scope, ev.Agent)
	case runevents.TypeAppLog:
		r.AddAppLogLines(1)
	}
}

// begin запоминает момент старта вызова инструмента.
//
// Повторный старт того же инструмента, пока предыдущий не завершён, НЕ затирает
// начало: иначе повторная доставка события обнулила бы длительность. Второй
// старт кладётся в очередь и будет забран первым же результатом.
func (r *Registry) begin(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if t := r.toolLocked(ev.Tool); t != nil {
		t.calls++
	}
	if s := r.scopeLocked(ev.Scope); s != nil {
		s.calls++
	}
	if a := r.agentLocked(ev.Agent); a != nil {
		a.calls++
	}
	r.toolCalls++
	r.pending[ev.Tool] = append(r.pending[ev.Tool], pending{agent: ev.Agent, scope: ev.Scope, at: ev.Time})
}

// end закрывает вызов инструмента и записывает длительность в гистограммы
// инструмента и scope.
func (r *Registry) end(ev runevents.Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	p, paired := r.takePendingLocked(ev.Tool)
	scope, agent := ev.Scope, ev.Agent
	if paired {
		if scope == "" {
			scope = p.scope
		}
		if agent == "" {
			agent = p.agent
		}
	}
	dur := 0.0
	if paired {
		dur = ev.Time.Sub(p.at).Seconds()
		if dur < 0 {
			dur = 0
		}
	} else {
		// Дедуп-корзина: результат без начала. Вызов не учитываем, длительность
		// нулевая — агрегаты остаются непротиворечивыми.
		r.unpaired++
		if t := r.toolLocked(ev.Tool); t != nil && t.calls > 0 {
			t.calls--
		}
		if s := r.scopeLocked(scope); s != nil && s.calls > 0 {
			s.calls--
		}
		if a := r.agentLocked(agent); a != nil && a.calls > 0 {
			a.calls--
		}
		r.toolCalls--
	}
	if !ev.OK {
		r.toolErrors++
	}
	if t := r.toolLocked(ev.Tool); t != nil {
		t.all.observe(dur)
		if !ev.OK {
			t.errors++
			t.failed.observe(dur)
		}
	}
	if s := r.scopeLocked(scope); s != nil {
		s.all.observe(dur)
		if !ev.OK {
			s.errors++
		}
	}
	if a := r.agentLocked(agent); a != nil && !ev.OK {
		a.errors++
	}
}

// takePendingLocked снимает самое раннее невыполненное начало вызова инструмента.
// Вызывается под mu.
func (r *Registry) takePendingLocked(tool string) (pending, bool) {
	q := r.pending[tool]
	if len(q) == 0 {
		return pending{}, false
	}
	if len(q) == 1 {
		delete(r.pending, tool)
	} else {
		r.pending[tool] = q[1:]
	}
	return q[0], true
}

// toolLocked возвращает агрегаты инструмента, создавая их при первом обращении.
func (r *Registry) toolLocked(name string) *toolStat {
	if name == "" {
		return nil
	}
	t, ok := r.tools[name]
	if !ok {
		t = &toolStat{all: newHistogram(), failed: newHistogram()}
		r.tools[name] = t
	}
	return t
}

// scopeLocked возвращает агрегаты единицы работы. Сверх maxSeries новые имена
// схлопываются в scopeOther, чтобы экспорт оставался конечным.
func (r *Registry) scopeLocked(scope string) *scopeStat {
	if scope == "" {
		return nil
	}
	if s, ok := r.scopes[scope]; ok {
		return s
	}
	if len(r.scopes) >= maxSeries {
		r.overflow++
		scope = scopeOther
		if s, ok := r.scopes[scope]; ok {
			return s
		}
	}
	s := &scopeStat{all: newHistogram()}
	r.scopes[scope] = s
	return s
}

// agentLocked возвращает агрегаты агента, создавая их при первом обращении.
func (r *Registry) agentLocked(name string) *agentStat {
	if name == "" {
		return nil
	}
	if a, ok := r.agents[name]; ok {
		return a
	}
	a := &agentStat{}
	r.agents[name] = a
	return a
}

// RecordTokens учитывает расход токенов раунда: глобальные итоги, итоги scope и
// агента, счётчик раундов и последнюю реальную скорость генерации.
// scope и agent необязательны (пустая строка — без атрибуции).
func (r *Registry) RecordTokens(in, out int64, tps float64, scope, agent string) {
	if in < 0 {
		in = 0
	}
	if out < 0 {
		out = 0
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.tokensIn += in
	r.tokensOut += out
	r.rounds++
	if tps > 0 {
		r.lastTPS = tps
	}
	if s := r.scopeLocked(scope); s != nil {
		s.tokensIn += in
		s.tokensOut += out
		s.rounds++
	}
	if a := r.agentLocked(agent); a != nil {
		a.tokensIn += in
		a.tokensOut += out
	}
}

// AddAppLogLines учитывает строки логов рантайма приложения (Ф-2), попавшие в
// поток событий агентского цикла.
func (r *Registry) AddAppLogLines(n int64) {
	if n <= 0 {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.appLogLines += n
}

// SetStepMetric записывает именованную метрику шага (перенос
// checkpoint.TrackMetric в единый реестр). Ключ составной — scope/step/key — и
// перезаписывается целиком, повторная запись того же шага НЕ накапливается.
func (r *Registry) SetStepMetric(scope, step, key string, value float64) {
	if step == "" || key == "" {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	r.stepMetric[metricKey(scope, step, key)] = value
}

// StepMetric возвращает записанное значение метрики шага.
func (r *Registry) StepMetric(scope, step, key string) (float64, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	v, ok := r.stepMetric[metricKey(scope, step, key)]
	return v, ok
}

// Reset обнуляет накопленные значения (сброс метрик в Web UI).
func (r *Registry) Reset() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.startedAt = time.Now()
	r.runID = r.startedAt.UnixNano()
	r.rounds, r.tokensIn, r.tokensOut = 0, 0, 0
	r.toolCalls, r.toolErrors, r.appLogLines, r.unpaired = 0, 0, 0, 0
	r.overflow = 0
	r.tools = map[string]*toolStat{}
	r.scopes = map[string]*scopeStat{}
	r.agents = map[string]*agentStat{}
	r.stepMetric = map[string]float64{}
	r.pending = map[string][]pending{}
}

func metricKey(scope, step, key string) string {
	return scope + "\x00" + step + "\x00" + key
}

// --- снимок ---

// ToolMetrics — агрегаты по инструменту.
type ToolMetrics struct {
	Tool    string  `json:"tool"`
	Calls   int64   `json:"calls"`
	Errors  int64   `json:"errors"`
	MeanSec float64 `json:"mean_sec"`
	MaxSec  float64 `json:"max_sec"`
}

// ScopeMetrics — агрегаты по единице работы.
type ScopeMetrics struct {
	Scope     string  `json:"scope"`
	Calls     int64   `json:"calls"`
	Errors    int64   `json:"errors"`
	Rounds    int64   `json:"rounds"`
	TokensIn  int64   `json:"tokens_in"`
	TokensOut int64   `json:"tokens_out"`
	TotalSec  float64 `json:"total_sec"`
	MeanSec   float64 `json:"mean_sec"`
}

// AgentMetrics — агрегаты по агенту.
type AgentMetrics struct {
	Agent     string `json:"agent"`
	Calls     int64  `json:"calls"`
	Errors    int64  `json:"errors"`
	TokensIn  int64  `json:"tokens_in"`
	TokensOut int64  `json:"tokens_out"`
}

// StepMetric — именованная метрика шага.
type StepMetric struct {
	Scope string  `json:"scope"`
	Step  string  `json:"step"`
	Key   string  `json:"key"`
	Value float64 `json:"value"`
}

// Snapshot — снимок реестра: всё, что нужно дашборду и /metrics.
type Snapshot struct {
	Project     string         `json:"project"`
	RunID       int64          `json:"run_id"`
	Since       time.Time      `json:"since"`
	UptimeSec   float64        `json:"uptime_sec"`
	Rounds      int64          `json:"rounds"`
	TokensIn    int64          `json:"tokens_in"`
	TokensOut   int64          `json:"tokens_out"`
	TokensTotal int64          `json:"tokens_total"`
	// PriceIn/PriceOut — цены за 1M токенов, по которым посчитана Cost.
	PriceIn  float64 `json:"price_in"`
	PriceOut float64 `json:"price_out"`
	Cost     float64 `json:"cost"`
	// CostKnown — заданы ли цены. Без них Cost всегда 0, а интерфейс
	// показывает токены без денежной оценки, а не выдуманный ноль.
	CostKnown   bool           `json:"cost_known"`
	LastTPS     float64        `json:"tps"`
	ToolCalls   int64          `json:"tool_calls"`
	ToolErrors  int64          `json:"tool_errors"`
	AppLogLines int64          `json:"app_log_lines"`
	Unpaired    int64          `json:"unpaired"`
	Overflow    int            `json:"overflow"`
	Tools       []ToolMetrics  `json:"tools"`
	Scopes      []ScopeMetrics `json:"scopes"`
	Agents      []AgentMetrics `json:"agents"`
	Steps       []StepMetric   `json:"steps"`
}

// Snapshot возвращает согласованный снимок реестра. Ряды отсортированы и
// уникальны по набору лейблов — требование формата Prometheus и одновременно
// дедуп: повторный экспорт одного и того же снимка даёт тот же текст.
func (r *Registry) Snapshot() Snapshot {
	r.mu.Lock()
	defer r.mu.Unlock()
	s := Snapshot{
		Project:     r.project,
		RunID:       r.runID,
		Since:       r.startedAt,
		UptimeSec:   time.Since(r.startedAt).Seconds(),
		Rounds:      r.rounds,
		TokensIn:    r.tokensIn,
		TokensOut:   r.tokensOut,
		TokensTotal: r.tokensIn + r.tokensOut,
		PriceIn:     r.pricing.InPerMillion,
		PriceOut:    r.pricing.OutPerMillion,
		CostKnown:   r.pricing.Known(),
		LastTPS:     r.lastTPS,
		ToolCalls:   r.toolCalls,
		ToolErrors:  r.toolErrors,
		AppLogLines: r.appLogLines,
		Unpaired:    r.unpaired,
		Overflow:    r.overflow,
	}
	if s.CostKnown {
		s.Cost = r.pricing.Cost(s.TokensIn, s.TokensOut)
	}
	for name, t := range r.tools {
		mean := 0.0
		if t.all.count > 0 {
			mean = t.all.sum / float64(t.all.count)
		}
		s.Tools = append(s.Tools, ToolMetrics{
			Tool: name, Calls: t.calls, Errors: t.errors,
			MeanSec: round3(mean), MaxSec: round3(t.approxMax()),
		})
	}
	sort.Slice(s.Tools, func(i, j int) bool { return s.Tools[i].Tool < s.Tools[j].Tool })
	for name, sc := range r.scopes {
		mean := 0.0
		if sc.all.count > 0 {
			mean = sc.all.sum / float64(sc.all.count)
		}
		s.Scopes = append(s.Scopes, ScopeMetrics{
			Scope: name, Calls: sc.calls, Errors: sc.errors, Rounds: sc.rounds,
			TokensIn: sc.tokensIn, TokensOut: sc.tokensOut,
			TotalSec: round3(sc.all.sum), MeanSec: round3(mean),
		})
	}
	sort.Slice(s.Scopes, func(i, j int) bool { return s.Scopes[i].Scope < s.Scopes[j].Scope })
	for name, a := range r.agents {
		s.Agents = append(s.Agents, AgentMetrics{
			Agent: name, Calls: a.calls, Errors: a.errors,
			TokensIn: a.tokensIn, TokensOut: a.tokensOut,
		})
	}
	sort.Slice(s.Agents, func(i, j int) bool { return s.Agents[i].Agent < s.Agents[j].Agent })
	for k, v := range r.stepMetric {
		parts := strings.SplitN(k, "\x00", 3)
		if len(parts) != 3 {
			continue
		}
		s.Steps = append(s.Steps, StepMetric{Scope: parts[0], Step: parts[1], Key: parts[2], Value: v})
	}
	sort.Slice(s.Steps, func(i, j int) bool {
		a, b := s.Steps[i], s.Steps[j]
		if a.Scope != b.Scope {
			return a.Scope < b.Scope
		}
		if a.Step != b.Step {
			return a.Step < b.Step
		}
		return a.Key < b.Key
	})
	return s
}

// approxMax — верхняя граница максимальной наблюдённой длительности.
// Гистограмма хранит только корзины, поэтому точное «максимум за шаг» не
// восстановить: отдаётся грубая верхняя оценка (нижняя граница самой полной
// корзины, либо потолок шкалы). Для дашборда этого достаточно, а память
// остаётся константной независимо от числа вызовов.
func (t *toolStat) approxMax() float64 {
	if t.all.count == 0 {
		return 0
	}
	for i := len(t.all.counts) - 1; i >= 0; i-- {
		if t.all.counts[i] == 0 {
			continue
		}
		if i == 0 {
			return stepBuckets[0]
		}
		return stepBuckets[i-1]
	}
	return stepBuckets[len(stepBuckets)-1]
}

func round3(v float64) float64 { return math.Round(v*1000) / 1000 }

// Цены токенов и оценка стоимости запуска.
//
// Ф-1 PLAN-2026-09-19-todo-owerview-for-prom.md. Счётчик токенов проекта
// existed и до этого этапа, но денежной оценки не было: Web UI показывал
// «вход/выход» без понимания, во сколько это обошлось. Цены задаёт пользователь
// (у провайдеров они разные и меняются), поэтому:
//
//	LLM_PRICE_IN  — цена 1M входных токенов;
//	LLM_PRICE_OUT — цена 1M выходных токенов.
//
// Без обеих переменных цена неизвестна: Known() == false, а интерфейс обязан
// показывать токены без денежной оценки, а не выдуманный ноль. Это тот же
// обязательный degrade, что и для Qdrant/LSP.
package tokens

import (
	"os"
	"strconv"
	"strings"
)

// Валюта по умолчанию для подписи метрик стоимости.
const DefaultCurrency = "у.е."

// Pricing — цены за 1M токенов входа и выхода.
type Pricing struct {
	InPerMillion  float64
	OutPerMillion float64
	// Currency — подпись валюты для отображения и метрик.
	Currency string
}

// Known сообщает, заданы ли цены. Без цен стоимость не вычисляется.
func (p Pricing) Known() bool { return p.InPerMillion > 0 || p.OutPerMillion > 0 }

// Cost возвращает стоимость расхода в валюте пользователя. Неизвестная цена
// считается нулём (Known() == false отличает «бесплатно» от «не знаем»).
func (p Pricing) Cost(in, out int64) float64 {
	if !p.Known() {
		return 0
	}
	return p.CostIn(in) + p.CostOut(out)
}

// CostIn — стоимость входных токенов.
func (p Pricing) CostIn(in int64) float64 {
	if in <= 0 {
		return 0
	}
	return float64(in) / 1_000_000 * p.InPerMillion
}

// CostOut — стоимость выходных токенов.
func (p Pricing) CostOut(out int64) float64 {
	if out <= 0 {
		return 0
	}
	return float64(out) / 1_000_000 * p.OutPerMillion
}

// PricingFromEnv читает цены из окружения. Любой нечисловой/отрицательный
// элемент игнорируется: цена по умолчанию — «не задана», а не «нулевая».
func PricingFromEnv() Pricing {
	p := Pricing{
		InPerMillion:  envPrice("LLM_PRICE_IN"),
		OutPerMillion: envPrice("LLM_PRICE_OUT"),
	}
	if v := strings.TrimSpace(os.Getenv("LLM_CURRENCY")); v != "" {
		p.Currency = v
	} else {
		p.Currency = DefaultCurrency
	}
	return p
}

func envPrice(name string) float64 {
	v := strings.TrimSpace(os.Getenv(name))
	if v == "" {
		return 0
	}
	f, err := strconv.ParseFloat(strings.ReplaceAll(v, ",", "."), 64)
	if err != nil || f < 0 {
		return 0
	}
	return f
}

// Экспорт реестра в текстовом формате Prometheus (Ф-1
// PLAN-2026-09-19-todo-owerview-for-prom.md).
//
// Формат — exposition text v0.0.4: HELP/TYPE-комментарии, затем ряды
// `имя{лейблы} значение [timestamp]`. Требования, которые снимок реестра
// выполняет по построению (см. Registry.Snapshot): у каждого набора лейблов
// ровно один ряд, порядок рядов стабильный, значения конечны.
package runmetrics

import (
	"bufio"
	"io"
	"strconv"
	"strings"
)

// WritePrometheus пишет снимок в формате Prometheus.
func (r *Registry) WritePrometheus(w io.Writer) error {
	return WritePrometheus(w, r.Snapshot())
}

// WritePrometheus пишет готовый снимок в формате Prometheus. Отдельная функция
// нужна серверу: он держит реестры по всем проектам и склеивает их в один
// ответ, не создавая снимок на каждый проект дважды.
func WritePrometheus(w io.Writer, snaps ...Snapshot) error {
	bw := bufio.NewWriter(w)
	for _, s := range snaps {
		writeSnapshot(bw, s)
	}
	return bw.Flush()
}

func writeSnapshot(bw *bufio.Writer, s Snapshot) {
	project := s.Project
	g := gauge(bw)
	c := counter(bw)
	h := histogramWriter(bw)

	// --- счётчики токенов и раундов ---
	c("run_tokens_total", "Потреблённые токены агентского цикла (direction=input/output).")
	labeled("run_tokens_total", "input", float64(s.TokensIn), project)
	labeled("run_tokens_total", "output", float64(s.TokensOut), project)

	c("run_rounds_total", "Раунды модели (вызовы LLM) за время наблюдения.")
	labeled("run_rounds_total", "", float64(s.Rounds), project)

	c("run_tool_calls_total", "Вызовы инструментов агентского цикла.")
	labeled("run_tool_calls_total", "", float64(s.ToolCalls), project)
	labeled("run_tool_errors_total", "Неуспешные вызовы инструментов.")
	labeled("run_tool_errors_total", "", float64(s.ToolErrors), project)
	labeled("run_tool_results_unpaired_total", "Результаты инструментов без парного начала (дедуп-корзина).")
	labeled("run_tool_results_unpaired_total", "", float64(s.Unpaired), project)
	labeled("run_app_log_lines_total", "Строки логов рантайма приложения, прочитанные инструментом ReadAppLogs.")
	labeled("run_app_log_lines_total", "", float64(s.AppLogLines), project)

	// --- стоимость ---
	// Цена — гейдж (задаётся конфигурацией), стоимость накопленного расхода —
	// счётчик, монотонно растущий. Без цен ряды не выводятся вовсе.
	if s.CostKnown {
		g("run_token_price_per_million", "Цена 1M токенов в валюте LLM_CURRENCY (direction=input/output).")
		labeled("run_token_price_per_million", "input", s.PriceIn, project)
		labeled("run_token_price_per_million", "output", s.PriceOut, project)
		c("run_cost_units_total", "Накопленная стоимость расхода токенов (kind=input/output/total).")
		labeled("run_cost_units_total", "input", round3(s.PriceIn*float64(s.TokensIn)/1_000_000), project)
		labeled("run_cost_units_total", "output", round3(s.PriceOut*float64(s.TokensOut)/1_000_000), project)
		labeled("run_cost_units_total", "total", round3(s.Cost), project)
	}

	// --- гейджи времени ---
	g("run_uptime_seconds", "Сколько наблюдается текущий запуск агентского цикла.")
	labeled("run_uptime_seconds", "", round3(s.UptimeSec), project)
	g("run_output_tps", "Последняя измеренная скорость генерации (вых. ток/с).")
	labeled("run_output_tps", "", round3(s.LastTPS), project)
	g("run_series_overflow", "Единицы работы, схлопнутые в scope=other из-за лимита кардинальности.")
	labeled("run_series_overflow", "", float64(s.Overflow), project)

	// --- гистограммы длительности вызовов ---
	for _, t := range s.Tools {
		// Гистограмма по инструменту: счётчики и сумма считаются из снимка
		// агрегатов, а count/sum выводит общий снимок — чтобы не тянуть в
		// экспорт внутренние счётчики реестра.
		call := t.Calls - t.Errors
		h("run_tool_duration_seconds", "Длительность вызовов инструмента.", project, []label{{"tool", t.Tool}, {"status", "ok"}}, float64(call), round3(t.MeanSec*float64(call)), stepBuckets, nil)
		h("run_tool_duration_seconds", "Длительность вызовов инструмента.", project, []label{{"tool", t.Tool}, {"status", "error"}}, float64(t.Errors), round3(t.MeanSec*float64(t.Errors)), stepBuckets, nil)
	}
	hAll("run_step_duration_seconds", "Длительность шагов (вызовов инструментов) по единицам работы.", project, s.Scopes)

	// --- именованные метрики шагов (единый реестр, бывший checkpoint) ---
	if len(s.Steps) > 0 {
		g("run_step_metric", "Именованные метрики шага: contract_changes, files_added, rounds, verdict.")
		for _, st := range s.Steps {
			row("run_step_metric", project, []label{
				{"scope", st.Scope}, {"step", st.Step}, {"key", st.Key},
			}, st.Value)
		}
	}
}

// --- мелкие помощники формата ---

type label struct{ name, value string }

func gauge(bw *bufio.Writer) func(string, string) {
	return func(name, help string) { header(bw, name, help, "gauge") }
}

func counter(bw *bufio.Writer) func(string, string) {
	return func(name, help string) { header(bw, name, help, "counter") }
}

// histogramWriter печатает один ряд гистограммы: le-корзины, затем +Inf, _sum
// и _count. buckets передаётся для будущих счётчиков; в текущей реализации
// ряды le строятся из готовых значений (hist) либо из равномерной сетки (nil).
func histogramWriter(bw *bufio.Writer) func(string, string, string, []label, float64, float64, []float64, []int64) {
	return func(name, help, project string, ls []label, count, sum float64, buckets []float64, hist []int64) {
		header(bw, name, help, "histogram")
		if hist != nil {
			for i, b := range buckets {
				row(name, project, withLabel(ls, "le", formatFloat(b)), float64(hist[i]))
			}
		}
		row(name, project, withLabel(ls, "le", "+Inf"), count)
		row(name+"_sum", project, ls, sum)
		row(name+"_count", project, ls, count)
	}
}

// hAll выводит одну общую гистограмму длительности шагов (счётчик и сумма в
// снимке не хранятся покорзиночно, поэтому le-корзины не выводятся; экспорт
// остаётся валидным, а точность для дашборда обеспечивает mean_sec).
func hAll(bw *bufio.Writer, name, help, project string, scopes []ScopeMetrics) {
	header(bw, name, help, "histogram")
	var calls, total float64
	for _, sc := range scopes {
		calls += float64(sc.Calls)
		total += sc.TotalSec
	}
	row(name+"_sum", project, nil, round3(total))
	row(name+"_count", project, nil, calls)
}

var seenHeader = map[string]bool{}

func header(bw *bufio.Writer, name, help, typ string) {
	// Заголовок печатается один раз на весь ответ: несколько проектов в одном
	// /metrics делят одни и те же имена метрик.
	if seenHeader[name] {
		return
	}
	seenHeader[name] = true
	bw.WriteString("# HELP " + name + " " + escapeHelp(help) + "\n")
	bw.WriteString("# TYPE " + name + " " + typ + "\n")
}

func labeled(name, dir string, v float64, project string) {
	var ls []label
	if dir != "" {
		ls = append(ls, label{"direction", dir})
	}
	row(name, project, ls, v)
}

func row(name, project string, ls []label, v float64) {
	var b strings.Builder
	b.WriteString(name)
	b.WriteString(labels(ls, project))
	b.WriteByte(' ')
	b.WriteString(formatFloat(v))
	b.WriteByte('\n')
	// bufio.Writer не возвращает ошибку записи в интерфейсе io.Writer без
	// проверки; текст метрик небольшой, а ошибку сокета поймает сам Handler.
	_, _ = io.WriteString(bw, b.String())
}

func labels(ls []label, project string) string {
	all := make([]label, 0, len(ls)+1)
	all = append(all, label{"project", project})
	all = append(all, ls...)
	var b strings.Builder
	b.WriteByte('{')
	for i, l := range all {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(l.name)
		b.WriteString(`="`)
		b.WriteString(escapeLabel(l.value))
		b.WriteByte('"')
	}
	b.WriteByte('}')
	return b.String()
}

func withLabel(ls []label, name, value string) []label {
	out := make([]label, 0, len(ls)+1)
	out = append(out, ls...)
	out = append(out, label{name, value})
	return out
}

func formatFloat(v float64) string {
	if v == float64(int64(v)) && v < 1e15 && v > -1e15 {
		return strconv.FormatInt(int64(v), 10)
	}
	return strconv.FormatFloat(v, 'g', -1, 64)
}

func escapeLabel(v string) string {
	return strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`).Replace(v)
}

func escapeHelp(v string) string {
	return strings.NewReplacer(`\`, `\\`, "\n", `\n`).Replace(v)
}

// Экспорт реестра в текстовом формате Prometheus (Ф-1
// PLAN-2026-09-19-todo-owerview-for-prom.md).
//
// Формат — exposition text v0.0.4: HELP/TYPE-комментарии, затем ряды
// `имя{лейблы} значение`. Требования, которые снимок реестра выполняет по
// построению (см. Registry.Snapshot): у каждого набора лейблов ровно один ряд,
// порядок рядов стабильный, значения конечны.
package runmetrics

import (
	"bufio"
	"io"
	"math"
	"strconv"
	"strings"
)

// WritePrometheus пишет снимок в формате Prometheus.
func (r *Registry) WritePrometheus(w io.Writer) error {
	return WritePrometheus(w, r.Snapshot())
}

// WritePrometheus склеивает снимки нескольких проектов в один ответ /metrics.
// Заголовки HELP/TYPE печатаются один раз на весь ответ: имена метрик общие,
// а отличаются только лейблы project.
func WritePrometheus(w io.Writer, snaps ...Snapshot) error {
	bw := bufio.NewWriter(w)
	seen := map[string]bool{}
	for _, s := range snaps {
		writeSnapshot(bw, seen, s)
	}
	return bw.Flush()
}

func writeSnapshot(bw *bufio.Writer, seen map[string]bool, s Snapshot) {
	project := s.Project

	// --- счётчики токенов и раундов ---
	counter(seen, bw, "run_tokens_total", "Потреблённые токены агентского цикла (direction=input/output).")
	row(bw, "run_tokens_total", project, dir("input"), float64(s.TokensIn))
	row(bw, "run_tokens_total", project, dir("output"), float64(s.TokensOut))

	counter(seen, bw, "run_rounds_total", "Раунды модели (вызовы LLM) за время наблюдения.")
	row(bw, "run_rounds_total", project, nil, float64(s.Rounds))

	counter(seen, bw, "run_tool_calls_total", "Вызовы инструментов агентского цикла.")
	row(bw, "run_tool_calls_total", project, nil, float64(s.ToolCalls))
	counter(seen, bw, "run_tool_errors_total", "Неуспешные вызовы инструментов.")
	row(bw, "run_tool_errors_total", project, nil, float64(s.ToolErrors))
	counter(seen, bw, "run_tool_results_unpaired_total", "Результаты инструментов без парного начала (дедуп-корзина).")
	row(bw, "run_tool_results_unpaired_total", project, nil, float64(s.Unpaired))
	counter(seen, bw, "run_app_log_lines_total", "Строки логов рантайма, прочитанные инструментом ReadAppLogs.")
	row(bw, "run_app_log_lines_total", project, nil, float64(s.AppLogLines))

	// --- стоимость ---
	// Цена — гейдж (задаётся конфигурацией), накопленный расход — счётчик.
	// Без заданных цен ряды не выводятся вовсе: нулевая стоимость при
	// неизвестной цене была бы выдумкой.
	if s.CostKnown {
		gauge(seen, bw, "run_token_price_per_million", "Цена 1M токенов в валюте LLM_CURRENCY (direction=input/output).")
		row(bw, "run_token_price_per_million", project, dir("input"), s.PriceIn)
		row(bw, "run_token_price_per_million", project, dir("output"), s.PriceOut)
		counter(seen, bw, "run_cost_units_total", "Накопленная стоимость расхода токенов (kind=input/output/total).")
		row(bw, "run_cost_units_total", project, dir("input"), round3(s.CostIn))
		row(bw, "run_cost_units_total", project, dir("output"), round3(s.CostOut))
		row(bw, "run_cost_units_total", project, dir("total"), round3(s.Cost))
	}

	// --- гейджи времени ---
	gauge(seen, bw, "run_uptime_seconds", "Сколько наблюдается текущий запуск агентского цикла.")
	row(bw, "run_uptime_seconds", project, nil, round3(s.UptimeSec))
	gauge(seen, bw, "run_output_tps", "Последняя измеренная скорость генерации (вых. ток/с).")
	row(bw, "run_output_tps", project, nil, round3(s.LastTPS))
	gauge(seen, bw, "run_series_overflow", "Единицы работы, схлопнутые в scope=other из-за лимита кардинальности.")
	row(bw, "run_series_overflow", project, nil, float64(s.Overflow))

	// --- гистограммы длительности вызовов ---
	const toolDurHelp = "Длительность вызовов инструмента агентского цикла."
	for _, t := range s.Tools {
		ls := []label{{"tool", t.Tool}}
		okCalls := t.Count - t.ErrorCount
		okSum := t.SumSec - t.ErrorSumSec
		hist(seen, bw, "run_tool_duration_seconds", toolDurHelp, project,
			appendStatus(ls, "ok"), okCalls, okSum, t.Buckets, t.ErrorBuckets, t.Count, t.SumSec)
		hist(seen, bw, "run_tool_duration_seconds", toolDurHelp, project,
			appendStatus(ls, "error"), t.ErrorCount, t.ErrorSumSec, t.Buckets, t.ErrorBuckets, t.Count, t.SumSec)
	}

	// Общая гистограмма шагов по всем единицам работы: счётчики и сумма берутся
	// из снимка (там, где серии нет, остаётся нулевой ряд — он тоже валиден).
	const stepDurHelp = "Длительность шагов (вызовов инструментов) агентского цикла."
	histogramHeader(seen, bw, "run_step_duration_seconds", stepDurHelp)
	row(bw, "run_step_duration_seconds_sum", project, nil, round3(s.StepSumSec))
	row(bw, "run_step_duration_seconds_count", project, nil, float64(s.StepCount))

	// --- именованные метрики шагов (единый реестр, бывший checkpoint) ---
	if len(s.Steps) > 0 {
		gauge(seen, bw, "run_step_metric", "Именованные метрики шага: contract_changes, files_added, rounds, verdict.")
		for _, st := range s.Steps {
			row(bw, "run_step_metric", project, []label{
				{"scope", st.Scope}, {"step", st.Step}, {"key", st.Key},
			}, st.Value)
		}
	}
}

// --- мелкие помощники формата ---

type label struct{ name, value string }

func header(seen map[string]bool, bw *bufio.Writer, name, help, typ string) {
	if seen[name] {
		return
	}
	seen[name] = true
	_, _ = io.WriteString(bw, "# HELP "+name+" "+escapeHelp(help)+"\n")
	_, _ = io.WriteString(bw, "# TYPE "+name+" "+typ+"\n")
}

func gauge(seen map[string]bool, bw *bufio.Writer, name, help string) {
	header(seen, bw, name, help, "gauge")
}

func counter(seen map[string]bool, bw *bufio.Writer, name, help string) {
	header(seen, bw, name, help, "counter")
}

func histogramHeader(seen map[string]bool, bw *bufio.Writer, name, help string) {
	header(seen, bw, name, help, "histogram")
}

// hist печатает гистограмму с набором лейблов ls. all — полный набор корзин и
// значений (count/sum), по которому восстанавливаются le-корзины выбранного
// статуса: так одна гистограмма инструмента публикуется дважды, по status=ok и
// status=error, из одного снимка.
func hist(seen map[string]bool, bw *bufio.Writer, name, help, project string, ls []label,
	count, sum float64, allBuckets, selBuckets []int64, allCount int64, allSum float64) {
	histogramHeader(seen, bw, name, help)
	for i, b := range stepBuckets {
		if i >= len(selBuckets) {
			break
		}
		row(bw, name, project, appendLe(ls, formatFloat(b)), float64(selBuckets[i]))
	}
	row(bw, name, project, appendLe(ls, "+Inf"), count)
	row(bw, name+"_sum", project, ls, round3(sum))
	row(bw, name+"_count", project, ls, count)
}

func appendStatus(ls []label, status string) []label {
	out := make([]label, 0, len(ls)+1)
	out = append(out, ls...)
	return append(out, label{"status", status})
}

func appendLe(ls []label, le string) []label {
	out := make([]label, 0, len(ls)+1)
	out = append(out, ls...)
	return append(out, label{"le", le})
}

func dir(d string) []label { return []label{{"direction", d}} }

func row(bw *bufio.Writer, name, project string, ls []label, v float64) {
	var b strings.Builder
	b.WriteString(name)
	b.WriteString(labels(ls, project))
	b.WriteByte(' ')
	b.WriteString(formatFloat(v))
	b.WriteByte('\n')
	_, _ = io.WriteString(bw, b.String())
}

func labels(ls []label, project string) string {
	all := make([]label, 0, len(ls)+1)
	all = append(all, label{"project", project})
	all = append(all, ls...)
	var b strings.Builder
	b.WriteByte('{')
	for i, l := range all {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(l.name)
		b.WriteString(`="`)
		b.WriteString(escapeLabel(l.value))
		b.WriteByte('"')
	}
	b.WriteByte('}')
	return b.String()
}

func formatFloat(v float64) string {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return "0"
	}
	if v == math.Trunc(v) && math.Abs(v) < 1e15 {
		return strconv.FormatInt(int64(v), 10)
	}
	return strconv.FormatFloat(v, 'g', -1, 64)
}

func escapeLabel(v string) string {
	return strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`).Replace(v)
}

func escapeHelp(v string) string {
	return strings.NewReplacer(`\`, `\\`, "\n", `\n`).Replace(v)
}

