		Parameters: map[string]any{
			"type":                 "object",
			"properties":           map[string]any{},
			"required":             []string{},
			"additionalProperties": false,
		},
	}
}

func (t *stackTool) Execute(args map[string]any) ([]byte, error) { return t.exec() }

