// makeInfraMirror возвращает зеркальную инфра-цель ('make infra.<цель>') для
// прикладной make-команды, если Makefile её объявляет. Контейнерный тулчейн
// Docker Compose, к которому приёмка переходит при недоступном инструменте
// хоста (exit 127/command not found).
func makeInfraMirror(targets map[string]bool, cmd string) string {
	t := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(cmd), "make "))
	if t == "" || t == strings.TrimSpace(cmd) || !targets["infra."+t] {
		return ""
	}
	return "make infra." + t
}

func hasFile(dir, name string) bool {
	info, err := os.Stat(filepath.Join(dir, name))
	return err == nil && !info.IsDir()
}

// buildCommand возвращает команду сборки проекта, определённую по типу.
// Пустая строка означает, что сборка для данного типа не требуется.
func (k Kind) buildCommand(dir string) string {
	switch k {
	case KindGo:
		return "go build ./..."
	case KindPhp:
		// PHP не компилируется: синтаксическая проверка всех .php через
		// php -l (аналог compileall у питона). Каталоги зависимостей не трогаем.
		return phpLintCmd()
	case KindNode:
		// Если есть npm-скрипт build — запускаем его, есть tsconfig без
		// скрипта — проверяем типы через tsc --noEmit. Иначе сборки нет.
		if nodeHasScript(dir, "build") {
			return "npm run build"
		}
		if hasFile(dir, "tsconfig.json") {
			return "npx tsc --noEmit"
		}
