 	t.mu.Lock()
 	defer t.mu.Unlock()
 	if n <= 0 || n > len(t.lines) {
 		n = len(t.lines)
 	}
 	out := make([]string, n)
 	copy(out, t.lines[len(t.lines)-n:])
 	return out
 }

