+// Снятие безопасно: если подписку уже заменили, cancel ничего не делает —
+// иначе вытесненная сессия погасила бы «рантайм» новой.
+func SetAppLogSink(dir string, fn func(source, line string)) (cancel func()) {
+	if dir == "" {
