 	case LspHover:
 		return &lspHoverTool{ops: deps.FileOps}
 	case CodeSearch:
 		return &codeSearchTool{ops: deps.FileOps, searcher: deps.RAG}
 	case RagIndexStatus:
 		return &ragIndexStatusTool{ops: deps.FileOps, searcher: deps.RAG}
 	case DetectStack:
