// нет (консольный режим), контекст возвращается без изменений.
func WithScope(ctx context.Context, scope string) context.Context {
	if r := ReporterFromContext(ctx); r != nil {
		return WithReporter(ctx, r.WithScope(scope))
	}
	return ctx
}

