package agents

// Тест согласованности промпта и набора инструментов (Ф-2 PLAN-2026-09-19-todo-owerview-for-prom.md).
//
// Проблема, которую он ловит: промпт советует агенту вызвать инструмент,
// которого в его наборе нет. Модель тогда либо выдумывает аргументы и получает
// «not in tool set», либо вообще игнорирует проверку — и «проверь в рантайме»
// превращается в пустую декларацию. Именно так молча пропадала инструкция про
// Makefile, когда цель в промпте была, а инструмента в наборе не было.
//
// Проверка обратная и строгая: если промпт называет инструмент из этого пакета
// по имени (как слово с заглавной буквы), инструмент обязан быть в наборе.
// Список «инструментов-упоминаний» — закрытый: новые упоминания надо вносить
// сюда руками, иначе тест их пропустит (см. knownPromptTools).

import (
	"strings"
	"testing"
)

// knownPromptTools — инструменты этого репозитория, которые промпты называют
// прямо по имени. Держим здесь, а не вылавливаем регуляркой по всему тексту:
// иначе в «упоминания» попадут слова вроде ReadAppLogs в комментариях к коду.
var knownPromptTools = []string{
	"WriteFiles", "ReadFiles", "ReadMap", "DeleteFiles", "Run", "List", "AppendFile",
	"SearchReplace", "PatchGoFunction", "DetectStack", "ReadAppLogs",
	"LspCheck", "LspDefinition", "LspReferences", "LspHover", "CodeSearch",
	"RagIndexStatus", "ResolveGitConflicts",
}

// toolSetsUnderTest — наборы инструментов и их промпты. Ключ — имя для отчёта.
var toolSetsUnderTest = []struct {
	name     string
	toolList []string
	prompt   string
}{
	{"backend developer", backendDevToolNames, backendDevPrompt},
	{"frontend developer", frontendDevToolNames, frontendDevPrompt},
	{"qa engineer", qaToolNames, qaPrompt},
	{"devops", devopsToolNames, devopsPrompt},
}

// TestPromptToolsAvailableInToolSet — каждое упомянутое в промпте имя должно
// быть в наборе инструментов агента.
func TestPromptToolsAvailableInToolSet(t *testing.T) {
	for _, ts := range toolSetsUnderTest {
		for _, want := range mentionedTools(ts.prompt) {
			if !contains(ts.toolList, want) {
				t.Errorf("%s: промпт называет %s, но инструмента нет в наборе %v", ts.name, want, ts.toolList)
			}
		}
	}
}

// TestReadAppLogsAvailableToRuntimeRoles — ReadAppLogs обязаны быть у всех
// ролей, которые реально запускают и проверяют приложение: разработчиков, QA и
// DevOps. Без инструмента в наборе инструкция «проверь в рантайме» неисполнима.
func TestReadAppLogsAvailableToRuntimeRoles(t *testing.T) {
	for _, ts := range toolSetsUnderTest {
		if !contains(ts.toolList, "ReadAppLogs") {
			t.Errorf("%s: в наборе нет ReadAppLogs — проверять рантайм нечем", ts.name)
		}
		if !mentions(ts.prompt, "ReadAppLogs") {
			t.Errorf("%s: промпт не упоминает ReadAppLogs", ts.name)
		}
	}
}

// TestReadAppLogsPromptWarnsAgainstRerun — в промпте должен быть запрет
// «перезапустить то же самое ради тех же строк»: без него модель в цикле
// самокоррекции жжёт раунды на повторные запуски (см. runner/applog.go).
func TestReadAppLogsPromptWarnsAgainstRerun(t *testing.T) {
	for _, ts := range toolSetsUnderTest {
		if !mentions(ts.prompt, "Рантайм") && !mentions(ts.prompt, "рантайм") {
			t.Errorf("%s: промпт не связывает ReadAppLogs с панелью «Рантайм»", ts.name)
		}
	}
}

// TestNoUnknownToolNamesInPrompts — в промптах не должно быть имён инструментов
// из knownPromptTools, которых нет в наборе (обратная сторона той же
// согласованности, ловит опечатки вида ReadAppLog).
func TestNoUnknownToolNamesInPrompts(t *testing.T) {
	// Опечатки и близкие имена, которые регулярно всплывают в промптах.
	typos := []string{"ReadAppLog ", "ReadAppLogsLog", "AppLogsRead", "PatchGoFunc", "CodeSerach"}
	for _, ts := range toolSetsUnderTest {
		for _, bad := range typos {
			if mentions(ts.prompt, bad) {
				t.Errorf("%s: в промпте опечатка в имени инструмента: %q", ts.name, bad)
			}
		}
	}
}

