 	Kind Kind
 }

 // DetectProjects находит проекты в директории приёмки:
 //   - если в корне есть маркер проекта (go.mod/package.json/…) — это один
 //     проект в корне (Rel == "");
 //   - иначе просматриваем прямые подкаталоги и возвращаем те, в которых
 //     есть собственные маркеры (фронтенд и бэкенд монорепозитория);
 //   - каталоги без маркеров и служебные (node_modules, dist, .git, …)
 //     игнорируются.
 //
 // Результат детерминирован: сортировка по имени подкаталога.
 func DetectProjects(dir string) []ProjectRoot {
 	if kind := DetectKind(dir); kind != KindUnknown {
 		return []ProjectRoot{{Dir: dir, Rel: "", Kind: kind}}
 	}

 	entries, err := os.ReadDir(dir)
 	if err != nil {
 		return nil
 	}
 	var roots []ProjectRoot
 	for _, e := range entries {
 		if !e.IsDir() {
 			continue
 		}
 		name := e.Name()
 		if strings.HasPrefix(name, ".") || isIgnoredDir(name) {
 			continue
 		}
 		sub := filepath.Join(dir, name)
 		if kind := DetectKind(sub); kind != KindUnknown {
 			roots = append(roots, ProjectRoot{Dir: sub, Rel: name, Kind: kind})
 		}
 	}
 	sort.Slice(roots, func(i, j int) bool { return roots[i].Rel < roots[j].Rel })
 	return roots
 }

 // makefileLocate ищет корневой Makefile проекта: от подпроекта dir вверх до
 // корня приёмки root включительно. Возвращает директорию с найденным файлом
 // и множество имён целей (пустые — Makefile не найден).
 func makefileLocate(root, dir string) (string, map[string]bool) {
 	for d := dir; ; {
 		if hasFile(d, "Makefile") {
 			return d, makefileTargets(filepath.Join(d, "Makefile"))
 		}
 		if d == root {
 			break
 		}
 		parent := filepath.Dir(d)
 		if parent == d {
 			break
 		}
 		d = parent
 	}
 	return "", nil
 }

 // makefileTargets парсит цели Makefile: строки вида «имя...:» до первого
 // двоеточия, с поддержкой нескольких имён-целей на одной строке
 // («build test: ...»). Пропускаются переменные («=»), шаблонные правила («%»),
 // служебные имена с ведущей точкой (.PHONY/.DEFAULT_GOAL/.ONESHELL) и имена
 // вне допустимого набора символов [A-Za-z0-9_.-]. Детерминированный, без сети.
 func makefileTargets(path string) map[string]bool {
 	data, err := os.ReadFile(path)
 	if err != nil {
 		return nil
 	}
 	targets := map[string]bool{}
 	for _, line := range strings.Split(string(data), "\n") {
 		line = strings.TrimSpace(line)
 		if line == "" || strings.HasPrefix(line, "#") {
 			continue
 		}
 		if !strings.Contains(line, ":") {
 			continue
 		}
 		name := strings.TrimSpace(strings.SplitN(line, ":", 2)[0])
 		if name == "" || strings.ContainsAny(name, "=%$") {
 			continue
 		}
 		// Присваивание переменной «SHELL := /bin/bash» — не цель.
 		if i := strings.Index(line, ":"); i+1 < len(line) && line[i+1] == '=' {
 			continue
 		}
 		names := strings.Fields(name)
 		if len(names) == 0 {
 			continue
 		}
 		clean := true
 		for _, n := range names {
 			if strings.HasPrefix(n, ".") || !makefileTargetName(n) {
 				clean = false
 				break
 			}
 		}
 		if !clean {
 			continue
 		}
 		for _, n := range names {
 			targets[n] = true
 		}
 	}
 	if len(targets) == 0 {
 		return nil
 	}
 	return targets
 }

 // makefileTargetName проверяет имя цели по контракту: только латиница,
 // цифры, подчёркивание, точка и дефис.
 func makefileTargetName(s string) bool {
 	for _, r := range s {
 		switch {
 		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9':
 		case r == '_', r == '.', r == '-':
 		default:
 			return false
 		}
 	}
 	return true
 }

 // makeCommand возвращает make-команду цели, если Makefile её объявляет
 // (приоритет Makefile выше автодетекта по типу: Р-5
 // PLAN-2026-09-24-todo-makefile.md).
 func makeCommand(targets map[string]bool, target string) string {
 	if targets[target] {
 		return "make " + target
 	}
 	return ""
 }

 // makeAnalyzeCommand выбирает цель анализатора: приоритет 'test', затем 'lint'
 // (дополнительная проверка через автотесты, если именно тесты объявлены).
 func makeAnalyzeCommand(targets map[string]bool) (cmd, tool string) {
 	switch {
 	case targets["test"]:
 		return "make test", "make test"
 	case targets["lint"]:
 		return "make lint", "make lint"
 	}
 	return "", ""
 }

 // makeInfraMirror возвращает зеркальную инфра-цель ('make infra.<цель>') для
 // прикладной make-команды, если Makefile её объявляет. Контейнерный тулчейн
 // Docker Compose, к которому приёмка переходит при недоступном инструменте
 // хоста (exit 127/command not found).
 func makeInfraMirror(targets map[string]bool, cmd string) string {
 	t := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(cmd), "make "))
 	if t == "" || t == strings.TrimSpace(cmd) || !targets["infra."+t] {
 		return ""
 	}
 	return "make infra." + t
 }

 func hasFile(dir, name string) bool {
 	info, err := os.Stat(filepath.Join(dir, name))
 	return err == nil && !info.IsDir()
 }

 // buildCommand возвращает команду сборки проекта, определённую по типу.
 // Пустая строка означает, что сборка для данного типа не требуется.
 func (k Kind) buildCommand(dir string) string {
 	switch k {
 	case KindGo:
 		return "go build ./..."
 	case KindPhp:
 		// PHP не компилируется: синтаксическая проверка всех .php через
 		// php -l (аналог compileall у питона). Каталоги зависимостей не трогаем.
 		return phpLintCmd()
 	case KindNode:
 		// Если есть npm-скрипт build — запускаем его, есть tsconfig без
 		// скрипта — проверяем типы через tsc --noEmit. Иначе сборки нет.
 		if nodeHasScript(dir, "build") {
 			return "npm run build"
 		}
 		if hasFile(dir, "tsconfig.json") {
 			return "npx tsc --noEmit"
 		}
 		return ""
 	case KindPython:
 		// Питон не компилируется, но syntax-check всех модулей ловит
 		// синтаксические ошибки до запуска (дёшево и быстро).
 		return pythonCmd() + " -m compileall -q ."
 	default:
 		return ""
 	}
 }

 // runCommand возвращает команду запуска приложения, определённую по типу.
 // Пустая строка означает, что точку входа определить не удалось.
 func (k Kind) runCommand(dir string) string {
 	switch k {
 	case KindGo:
 		if hasFile(dir, "main.go") {
 			return "go run ."
 		}
 		if mainPkg := findGoMainPkg(dir); mainPkg != "" {
 			return "go run " + mainPkg
 		}
 		return ""
 	case KindPhp:
 		// Laravel и другие фреймворки: artisan serve. «Голый» PHP — встроенный
 		// сервер; при наличии public/ точка входа находится там.
 		if hasFile(dir, "artisan") {
 			return "php artisan serve --host=127.0.0.1 --port=8080"
 		}
 		if hasFile(dir, "public/index.php") {
 			return "php -S 127.0.0.1:8080 -t public"
 		}
 		if hasFile(dir, "index.php") {
 			return "php -S 127.0.0.1:8080"
 		}
 		return ""
 	case KindNode:
 		if sc := nodeStartScript(dir); sc != "" {
 			return sc
 		}
 		if m := nodeMain(dir); m != "" {
 			return "node " + m
 		}
 		if nodeHasEntryFile(dir) {
 			return "node ."
 		}
 		// Статический фронтенд (Vite/React/Vue и т.п.): есть build-скрипт,
 		// но нет серверной точки входа для запуска — приёмка по сборке
 		// достаточна, запуск не требуется.
 		return ""
 	case KindPython:
 		if hasFile(dir, "main.py") {
 			return pythonCmd() + " main.py"
 		}
 		if hasFile(dir, "app.py") {
 			return pythonCmd() + " app.py"
 		}
 		return ""
 	default:
 		return ""
 	}
 }

 // formatCommand возвращает команду проверки стилизатора и название
 // инструмента. Пустая команда — стилизатор для проекта не найден/не настроен.
 // Команда не должна МЕНЯТЬ файлы — только сообщать о нарушениях.
 func (k Kind) formatCommand(dir string) (cmd, tool string) {
 	switch k {
 	case KindGo:
 		// gofmt -l печатает список неотформатированных файлов и завершается 0.
 		return "find . -name '*.go' -not -path './vendor/*' -print0 | xargs -0 -r gofmt -l", "gofmt"
 	case KindPhp:
 		// php-cs-fixer живёт в vendor/bin (composer require --dev). Без него
 		// стилизатор не найден — проверка пропускается.
 		if hasFile(dir, "vendor/bin/php-cs-fixer") {
 			return "vendor/bin/php-cs-fixer fix --dry-run --diff", "php-cs-fixer"
 		}
 		return "", ""
 	case KindNode:
 		// Только локальные бинари (npx умеет качать из сети — не для приёмки).
 		if hasNodeBin(dir, "prettier") {
 			return "./node_modules/.bin/prettier --check .", "prettier"
 		}
 		return "", ""
 	case KindPython:
 		if cmdAvailable("black") {
 			return "black --check .", "black"
 		}
 		return "", ""
 	default:
 		return "", ""
 	}
 }

 // analyzeCommand возвращает команду проверки анализатора и название
 // инструмента. Пустая команда — анализатор не найден/не настроен.
 func (k Kind) analyzeCommand(dir string) (cmd, tool string) {
 	switch k {
 	case KindGo:
 		return "go vet ./...", "go vet"
 	case KindPhp:
 		// phpstan — точный анализатор (raw-формат file:line:message удобен
 		// парсеру замечаний). Без конфигурации phpstan анализировать нечего —
 		// фолбэк на синтаксическую проверку php -l.
 		bin := ""
 		if hasFile(dir, "vendor/bin/phpstan") {
 			bin = "vendor/bin/phpstan"
 		} else if cmdAvailable("phpstan") {
 			bin = "phpstan"
 		}
 		if bin != "" &&
 			(hasFile(dir, "phpstan.neon") || hasFile(dir, "phpstan.neon.dist") || hasFile(dir, "phpstan.dist.neon")) {
 			return bin + " analyse --no-progress --error-format=raw", "phpstan"
 		}
 		return phpLintCmd(), "php -l"
 	case KindNode:
 		// Приоритет: скрипт lint в package.json, затем локальный eslint.
 		if pj := readPackageJSON(dir); pj != nil && pj.Scripts["lint"] != "" && hasFile(dir, "node_modules") {
 			return "npm run lint", "npm run lint"
 		}
 		if hasNodeBin(dir, "eslint") {
 			return "./node_modules/.bin/eslint .", "eslint"
 		}
 		return "", ""
 	case KindPython:
 		if cmdAvailable("ruff") {
 			return "ruff check .", "ruff"
 		}
 		if cmdAvailable("flake8") {
 			return "flake8 .", "flake8"
 		}
 		return "", ""
 	default:
 		return "", ""
 	}
 }

+// testCommand возвращает команду запуска автотестов проекта и название
+// инструмента. Пустая команда — запускать нечем (манифеста зависимостей нет,
+// тестов в проекте не предполагается, например для каталога только с
+// K8s-манифестами).
+//
+// Приоритет Makefile (цель test) и env ACCEPT_TEST_CMD разруливает вызывающая
+// сторона (VerifyPlanFor) — здесь только автодетект по типу проекта.
+func (k Kind) testCommand(dir string) (cmd, tool string) {
