 // сервисы поднимаются, и единственный способ это увидеть — прочитать логи
 // сервиса.
 func TestPromptMentionsOnlyAvailableTools(t *testing.T) {
 	d, err := NewDevopsInDir("задание", t.TempDir())
 	if err != nil {
 		t.Fatal(err)
