+		t.Errorf("в песочнице недопустимы --privileged/--network host: %s", args)
+	}
+	if !strings.Contains(args, "--user "+sandboxHostUser()) && sandboxHostUser() != "" {
+		t.Errorf("контейнер должен работать как non-root с UID/GID хоста: %s", args)
+	}
+}
