		MaxRounds:      3,
		CheckFormat:    true,
		AutoFormat:     true,
		CheckAnalyze:   true,
		CheckLSP:       true,
		InstallDeps:    true,
		InstallTimeout: 5 * time.Minute,
		MaxLog:         6000,
	}
}

