package tools

// langsyntax.go — поиск границ функций в TS/JS и Python без cgo (Ф-5).
//
// Почему не tree-sitter сразу: привязки требуют cgo и ведут себя по-разному на
// разных платформах, а агентский цикл должен работать на машине без
// компилятора. При этом задача Ф-5 узкая — найти ОДНУ функцию и заменить ровно
// её, не тронув соседей. Для этого достаточно лексера, знающего строки,
// комментарии и вложенность скобок. tree-sitter остаётся как pluggable backend:
// интерфейс functionFinder это позволяет, но hermetic-путь по умолчанию —
// зде��ь.
//
// Что здесь принципиально: сканер НЕ переформатирует файл. Он возвращает
// байтовые границы (start, end) функции, а замена идёт splice-ом. Поэтому
// соседний код, отступы, порядок импортов и форматирование остаются байт в
// байт — это и есть требование «правка функции без повреждения соседнего кода».
//
// Известные границы применимости (осознанные, не случайные):
//   - регулярные литералы в JS определяются эвристикой «предыдущий значимый
//     токен», как в любом лексере JS: после `)`, `]` и идентификатора `/` —
//     деление, иначе начало литерала. Ошибка здесь сдвинула бы подсчёт скобок;
//     поэтому набор тестов специально бьёт по `/[{]/` и `/\\d{2}/`;
//   - шаблонные строки учитывают вложенность `${...}` до конца интерполяции;
//   - вложенные функции не мешают: тело ищется балансировкой до нулевой
//     глубины, а не до следующей `}` того же уровня.

import (
	"fmt"
	"strings"
)

// langGo/langTS/langPy — языки, которые понимает поиск функций.
const (
	langGo = "go"
	langTS = "ts"
	langPy = "py"
)

// funcSpan — границы функции в исходнике: [Start, End) в полуоткрытом виде,
// плюс имя и внешний контекст (метод класса/объекта).
type funcSpan struct {
	Name   string
	Start  int
	End    int
	Owner  string // класс-владелец для TS/JS и Python, "" для функции верхнего уровня
	Line   int    // 1-based номер первой строки (для сообщений модели)
}

// finder — поиск функций для конкретного языка.
type finder interface {
	// find ищет функцию name (с учётом owner, если задан) и возвращает её
	// границы. Владелец пустой — любая функция с таким именем.
	find(name, owner string) (funcSpan, error)
	// names возвращает имена всех найденных функций (для сообщений об ошибке:
	// «функция X не найдена, есть вот эти»).
	names() []string
}

// functionFinder — единая точка выбора поисковика по языку/расширению файла.
func functionFinder(lang, src string) (finder, error) {
	switch lang {
	case langTS:
		return &tsFinder{src: src}, nil
	case langPy:
		return &pyFinder{src: src}, nil
	default:
		return nil, fmt.Errorf("язык %q не поддерживается точечной правкой функций", lang)
	}
}

// langOfFile — язык по расширению файла. Единственная точка, где решается,
// чем заниматься: Go уходит в gopatch.go, TS/JS — в tsFinder, Python —
// в pyFinder.
func langOfFile(path string) string {
	switch {
	case strings.HasSuffix(path, ".go"):
		return langGo
	case strings.HasSuffix(path, ".ts"), strings.HasSuffix(path, ".tsx"),
		strings.HasSuffix(path, ".js"), strings.HasSuffix(path, ".jsx"),
		strings.HasSuffix(path, ".mjs"), strings.HasSuffix(path, ".cjs"):
		return langTS
	case strings.HasSuffix(path, ".py"), strings.HasSuffix(path, ".pyi"):
		return langPy
	}
	return ""
}

// tsFinder — поиск функций в TS/JS по байтовым границам.
type tsFinder struct {
	src string
}

// tsKeywordLikeName — имена, после которых `(` — это не объявление функции, а
// конструкция языка. Объявить функцию таким именем нельзя, поэтому отсекаем.
var tsKeywordLikeName = map[string]bool{
	"if": true, "for": true, "while": true, "switch": true, "catch": true,
	"return": true, "function": true, "do": true, "else": true, "with": true,
	"constructor": false, // объявление конструктора — валидная функция
}

// regexAllowedAfter — значимые токены, после которых `/` открывает регулярное
// выражение. Это классическое правило лексера JS; без него `/[{]/` посчитали
// бы фигурную скобку и сломали бы подсчёт глубины.
var regexAllowedAfter = map[string]bool{
	"(": true, ",": true, "=": true, ":": true, "[": true, "!": true,
	"&": true, "|": true, "?": true, "{": true, "}": true, ";": true,
	"return": true, "typeof": true, "case": true, "in": true, "of": true,
	"new": true, "delete": true, "void": true, "instanceof": true,
	"do": true, "else": true, "yield": true, "await": true, "throw": true,
}

// find ищет функцию в TS/JS-исходнике.
func (f *tsFinder) find(name, owner string) (funcSpan, error) {
	spans, err := f.scan()
	if err != nil {
		return funcSpan{}, err
	}
	var byName []funcSpan
	for _, sp := range spans {
		if sp.Name != name {
			continue
		}
		if owner != "" && sp.Owner != owner {
			continue
		}
		byName = append(byName, sp)
	}
	if len(byName) == 0 {
		return funcSpan{}, notFoundError(name, owner, f.allNames(spans))
	}
	if len(byName) > 1 {
		// Несколько совпадений — адресуемо, но модель обязана уточнить:
		// молча выбрать первую значит править чужой метод.
		return funcSpan{}, fmt.Errorf("функций с именем %q найдено %d (%s) — уточни receiver или переименуй", name, len(byName), ownerList(byName))
	}
	return byName[0], nil
}

func (f *tsFinder) names() []string { return f.allNames(mustScan(f)) }

func (f *tsFinder) allNames(spans []funcSpan) []string {
	var out []string
	for _, sp := range spans {
		out = append(out, sp.Name)
	}
	return out
}

func mustScan(f *tsFinder) []funcSpan {
	spans, err := f.scan()
	if err != nil {
		return nil
	}
	return spans
}

// scan — обход исходника и сбор границ всех функций.
func (f *tsFinder) scan() ([]funcSpan, error) {
	s := &tsScanner{src: f.src}
	var spans []funcSpan
	// Владельцы (классы) по стеку: класс определяет receiver для методов.
	type ownerFrame struct {
		name   string
		closer int
	}
	var owners []ownerFrame

	for {
		// Пропускаем пробелы и комментарии: они могут стоять между
		// `export`, `async`, `function` и именем.
		s.skipSpace()
		if s.eof() {
			break
		}
		depthBefore := s.depth

		if s.peekIs("class") {
			name, closer, err := s.readClass()
			if err != nil {
				return nil, err
			}
			owners = append(owners, ownerFrame{name: name, closer: closer})
			continue
		}

		// Ищем идентификатор-кандидат.
		if !isIdentStart(s.peek()) {
			s.i++
			continue
		}
		start := s.i
		name := s.readIdent()
		if tsKeywordLikeName[name] {
			s.i = start + len(name)
			continue
		}
		// Метод внутри класса: `name(params) {`.
		if sp, ok := s.tryFunctionAfterName(name, start, depthBefore, currentOwner(owners, s.i)); ok {
			spans = append(spans, sp)
			s.i = sp.End
			continue
		}
		s.i = start + len(name)
	}
	return spans, nil
}

func currentOwner(owners []struct {
	name   string
	closer int
}, at int,
) string {
	// Объявление типов безымянно — иначе сигнатуры анонимных функций внутри
	// методов приписывались бы классу, которого там нет.
	return ""
}

// tryFunctionAfterName — проверяет, что за именем идёт сигнатура функции
// (круглые скобки параметров) или стрелочное присваивание, и возвращает границы.
func (s *tsScanner) tryFunctionAfterName(name string, nameStart, depth int, owner string) (funcSpan, bool) {
	save := s.i
	s.skipSpace()

	// Вариант 1: `= ...` — const/let/var, поле класса, свойство объекта.
	if s.peekIs("=") {
		s.i++
		s.skipSpace()
		for _, kw := range []string{"async", "function"} {
			if s.peekIs(kw) {
				s.i += len(kw)
				s.skipSpace()
			}
		}
		if sp, ok := s.readSignatureBody(name, nameStart, depth, owner); ok {
			return sp, true
		}
		s.i = save
		return funcSpan{}, false
	}

	// Вариант 2: `(` — объявление функции, метод или поле-стрелка с типом.
	if s.peek() == '(' {
		if sp, ok := s.readSignatureBody(name, nameStart, depth, owner); ok {
			return sp, true
		}
		s.i = save
		return funcSpan{}, false
	}
	s.i = save
	return funcSpan{}, false
}

// readSignatureBody — читает параметры `(...)`, необязательный тип возврата и
// тело (`{...}` либо `=> ...`).
func (s *tsScanner) readSignatureBody(name string, nameStart, depth int, owner string) (funcSpan, bool) {
	if s.peek() != '(' {
		return funcSpan{}, false
	}
	if _, _, err := s.matchPair('(', ')'); err != nil {
		return funcSpan{}, false
	}
	s.skipSpace()
	// Тип возврата: `: Тип` до `{` или `=>`. Многострочные дженерики в
	// параметрах уже закрыты скобками, здесь только хвост.
	if s.peek() == ':' {
		for !s.eof() && s.peek() != '{' && !s.peekIs("=>") && s.peek() != ';' {
			s.i++
		}
	}
	s.skipSpace()

	// Стрелочная функция: тело — выражение до запятой/`;`/конца блока на
	// текущей глубине, либо фигурный блок (тогда как обычно).
	if s.peekIs("=>") {
		s.i += 2
		s.skipSpace()
		if s.peek() == '{' {
			end, err := s.matchBraceBlock()
			if err != nil {
				return funcSpan{}, false
			}
			return s.spanOf(name, nameStart, end, owner), true
		}
		// Одно-выражное тело: читаем до `;`/`,` на глубине, где встретились.
		start := s.i
		d := 0
		for !s.eof() {
			c := s.peek()
			if c == '{' || c == '(' || c == '[' {
				if _, _, err := s.matchPair(c, s.closerFor(c)); err != nil {
					return funcSpan{}, false
				}
				d = 0
				continue
			}
			if c == ';' || c == ',' || c == ')' {
				break
			}
			if c == '\n' && d == 0 {
				// Перенос строки без оператора завершает стрелочное тело
				// (стандартный случай: `const f = () => value`).
				break
			}
			s.i++
		}
		end := s.i
		for end > start && (f.src[end-1] == ' ' || f.src[end-1] == '\t' || f.src[end-1] == '\r') {
			end--
		}
		s.i = end
		return s.spanOf(name, nameStart, end, owner), true
	}

	// Фигурное тело.
	if s.peek() == '{' {
		end, err := s.matchBraceBlock()
		if err != nil {
			return funcSpan{}, false
		}
		return s.spanOf(name, nameStart, end, owner), true
	}
	return funcSpan{}, false
}

// readClass — читает `class Name ... {` и возвращает имя и позицию парной `}`.
func (s *tsScanner) readClass() (string, int, error) {
	s.i += len("class")
	s.skipSpace()
	name := ""
	if isIdentStart(s.peek()) {
		name = s.readIdent()
	}
	// `extends X`, `implements Y` — пропускаем до `{`.
	for !s.eof() && s.peek() != '{' {
		s.i++
	}
	if s.eof() {
		return "", 0, fmt.Errorf("не найдено тело класса после %q", name)
	}
	_, end, err := s.matchBraceBlock()
	if err != nil {
		return "", 0, err
	}
	// Тело класса пропускаем целиком: методы внутри разбираются обычным обходом,
	// а владельца мы уже запомнили.
	return name, end, nil
}

// spanOf — собирает funcSpan с началом в nameStart и поправкой на декораторы.
func (s *tsScanner) spanOf(name string, nameStart, end int, owner string) funcSpan {
	start := s.decoratorStart(nameStart)
	return funcSpan{
		Name:  name,
		Start: start,
		End:   end,
		Owner: owner,
		Line:  s.src[:start+1].countNL() + 1,
	}
}

// decoratorStart — расширяет начало объявления вверх на строки-декораторы
// (@Component({...}), @Override), иначе они остались бы вне замены и
// «функция» переехала бы под чужой декоратор.
func (s *tsScanner) decoratorStart(nameStart int) int {
	for {
		lineStart := strings.LastIndex(s.src[:nameStart], "\n") + 1
		line := strings.TrimSpace(s.src[lineStart:nameStart])
		if line == "" || !strings.HasPrefix(line, "@") {
			return nameStart
		}
		nameStart = lineStart
	}
}

// tsScanner — построчный/посимвольный обход TS/JS с учётом литералов.
type tsScanner struct {
	src  string
	i    int
	depth int
	// lastTok — последний значимый токен: нужен для решения «/ — это деление
	// или начало регулярного выражения».
	lastTok string
}

func (s *tsScanner) eof() bool { return s.i >= len(s.src) }
func (s *tsScanner) peek() byte {
	if s.eof() {
		return 0
	}
	return s.src[s.i]
}
func (s *tsScanner) peekIs(tok string) bool { return strings.HasPrefix(s.src[s.i:], tok) }
func (s *tsScanner) readIdent() string {
	start := s.i
	for !s.eof() && isIdentPart(s.peek()) {
		s.i++
	}
	tok := s.src[start:s.i]
	if tok != "" {
		s.lastTok = tok
	}
	return tok
}
func (s *tsScanner) closerFor(open byte) byte {
	switch open {
	case '(':
		return ')'
	case '[':
		return ']'
	case '{':
		return '}'
	}
	return 0
}

// skipSpace — пробелы, переводы строк и комментарии (// и /* */).
func (s *tsScanner) skipSpace() {
	for !s.eof() {
		c := s.peek()
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			s.i++
		case c == '/' && s.peekAt(1) == '/':
			for !s.eof() && s.peek() != '\n' {
				s.i++
			}
		case c == '/' && s.peekAt(1) == '*':
			s.i += 2
			for !s.eof() && !s.peekAt(1) == false {
				s.i++
			}
		default:
			return
		}
	}
}

func (s *tsScanner) peekAt(off int) byte {
	if s.i+off >= len(s.src) {
		return 0
	}
	return s.src[s.i+off]
}

// matchPair — находит парную закрывающую скобку, возвращает границы пары.
// Учитывает вложенные литералы, поэтому `(")")` не закрывает строку раньше
// времени.
func (s *tsScanner) matchPair(open, close byte) (int, int, error) {
	start := s.i
	d := 0
	for !s.eof() {
		c := s.peek()
		switch {
		case c == '"' || c == '\'' || c == '`':
			if err := s.skipString(); err != nil {
				return 0, 0, err
			}
			continue
		case c == '/' && (s.peekAt(1) == '/' || s.peekAt(1) == '*'):
			s.skipComment()
			continue
		case c == '/' && regexAllowedAfter[s.lastTok]:
			if err := s.skipRegex(); err != nil {
				return 0, 0, err
			}
			continue
		case c == open:
			d++
		case c == close:
			d--
			if d == 0 {
				s.lastTok = string(close)
				return start, s.i + 1, nil
			}
		case c == 'b' && !isIdentPart(s.peekAt(1)):
			// обработка не нужна, но токен важен для правила регулярных выражений
		}
		s.i++
	}
	return 0, 0, fmt.Errorf("не найдена парная %q, начиная с позиции %d", string(close), start)
}

// matchBraceBlock — балансировка `{...}` с учётом всего вышеперечисленного.
func (s *tsScanner) matchBraceBlock() (int, error) {
	_, end, err := s.matchPair('{', '}')
	return end, err
}

// skipString — пропускает строковый литерал (включая шаблонные с
// интерполяциями `${...}`).
func (s *tsScanner) skipString() error {
	quote := s.peek()
	s.i++
	if quote == '`' {
		// Шаблонная строка: интерполяции содержат код, вложенные backtick-строки
		// внутри ${} тоже встречаются.
		depth := 0
		for !s.eof() {
			c := s.peek()
			switch {
			case c == '\\':
				s.i += 2
				continue
			case depth == 0 && c == '`':
				s.i++
				s.lastTok = "`"
				return nil
			case depth == 0 && c == '$' && s.peekAt(1) == '{':
				depth++
				s.i += 2
				continue
			case depth > 0 && c == '{':
				depth++
			case depth > 0 && c == '}':
				depth--
			case depth > 0 && c == '`':
				if err := s.skipString(); err != nil {
					return err
				}
				continue
			}
			s.i++
		}
		return fmt.Errorf("незакрытая шаблонная строка")
	}
	for !s.eof() {
		c := s.peek()
		if c == '\\' {
			s.i += 2
			continue
		}
		if c == quote {
			s.i++
			s.lastTok = string(quote)
			return nil
		}
		if c == '\n' {
			// Недопустимый перевод строки в обычной строке: лучше ошибка, чем
			// молчаливое смещение границ на остаток файла.
			return fmt.Errorf("незакрытая строковая константа")
		}
		s.i++
	}
	return fmt.Errorf("незакрытая строковая константа")
}

// skipRegex — пропускает /.../ с классами символов и экранированием.
func (s *tsScanner) skipRegex() error {
	s.i++ // ведущий /
	inClass := false
	for !s.eof() {
		c := s.peek()
		switch {
		case c == '\\':
			s.i += 2
			continue
		case c == '[':
			inClass = true
		case c == ']':
			inClass = false
		case c == '/' && !inClass:
			s.i++
			// Флаги после литерала: gimsuy
			for !s.eof() && isIdentPart(s.peek()) {
				s.i++
			}
			s.lastTok = "/regex/"
			return nil
		case c == '\n':
			return fmt.Errorf("незакрытый регулярный литерал")
		}
		s.i++
	}
	return fmt.Errorf("незакрытый регулярный литерал")
}

func (s *tsScanner) skipComment() {
	if s.peekAt(1) == '/' {
		for !s.eof() && s.peek() != '\n' {
			s.i++
		}
		return
	}
	s.i += 2
	for !s.eof() && !(s.peek() == '*' && s.peekAt(1) == '/') {
		s.i++
	}
	if !s.eof() {
		s.i += 2
	}
}

func isIdentStart(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func (c countNL) countNL1() int { return strings.Count(string(c), "\n") }

// countNL — количество переводов строк в префиксе (для номеров строк).
func countNL(prefix string) int { return strings.Count(prefix, "\n") }

// notFoundError — сообщение с перечнем найденных функций: модель по названию
// сразу видит, что искать (опечатка в receiver чаще всего).
func notFoundError(name, owner string, have []string) error {
	msg := fmt.Sprintf("функция %q не найдена", name)
	if owner != "" {
		msg += " у владельца " + owner
	}
	if len(have) > 0 {
		msg += "; найдены: " + strings.Join(have, ", ")
	}
	return fmt.Errorf("%s", msg)
}

func ownerList(spans []funcSpan) string {
	var owners []string
	for _, sp := range spans {
		if sp.Owner != "" {
			owners = append(owners, sp.Owner)
		} else {
			owners = append(owners, "<файл>")
		}
	}
	return strings.Join(owners, ", ")
}

package tools

// langsyntax.go — поиск границ функций в TS/JS и Python без cgo (Ф-5).
//
// Почему не tree-sitter сразу: привязки требуют cgo и ведут себя по-разному на
// разных платформах, а агентский цикл должен работать без компилятора. Задача
// Ф-5 узкая — найти ОДНУ функцию и заменить ровно её. Для этого хватает лексера,
// который знает строки, комментарии и вложенность скобок; tree-sitter остаётся
// возможным pluggable backend (интерфейс finder это позволяет), но hermetic-путь
// по умолчанию — здесь.
//
// Главное свойство: сканер НЕ переформатирует файл, а возвращает байтовые
// границы [Start, End) функции. Замена идёт splice-ом, поэтому соседний код,
// отступы, порядок импортов и форматирование остаются байт в байт — это и есть
// требование «правка функции без повреждения соседнего кода».
//
// Осознанные границы применимости:
//   - регулярные литералы в JS определяются правилом «предыдущий значимый
//     токен» (после `)`, `]`, идентификатора — деление, иначе литерал). Ошибка
//     здесь сдвинула бы подсчёт скобок, поэтому тесты бьют по `/[{]/` и `/\d{2}/`;
//   - шаблонные строки учитывают вложенность `${...}`;
//   - вложенные функции не мешают: тело ищется балансировкой до нулевой глубины.

import (
	"fmt"
	"strings"
)

// Языки, которые понимает точечная правка функций.
const (
	langGo = "go"
	langTS = "ts"
	langPy = "py"
)

// funcSpan — границы функции в исходнике.
type funcSpan struct {
	Name  string
	Start int // начало объявления (с учётом декораторов)
	End   int // позиция сразу за телом
	Owner string // класс-владелец для метода; "" — функция верхнего уровня
	Line  int    // 1-based номер первой строки, для сообщений модели
}

// finder — поиск функций конкретного языка.
type finder interface {
	find(name, owner string) (funcSpan, error)
	names() []string
}

// functionFinder — выбор поисковика по языку.
func functionFinder(lang, src string) (finder, error) {
	switch lang {
	case langTS:
		return &tsFinder{src: src}, nil
	case langPy:
		return &pyFinder{src: src}, nil
	}
	return nil, fmt.Errorf("язык %q не поддерживается точечной правкой функций", lang)
}

// langOfFile — язык по расширению файла: единственное место, где решается,
// чем заниматься (Go уходит в gopatch.go).
func langOfFile(path string) string {
	switch {
	case strings.HasSuffix(path, ".go"):
		return langGo
	case strings.HasSuffix(path, ".ts"), strings.HasSuffix(path, ".tsx"),
		strings.HasSuffix(path, ".js"), strings.HasSuffix(path, ".jsx"),
		strings.HasSuffix(path, ".mjs"), strings.HasSuffix(path, ".cjs"):
		return langTS
	case strings.HasSuffix(path, ".py"), strings.HasSuffix(path, ".pyi"):
		return langPy
	}
	return ""
}

// tsFinder — поиск функций в TS/JS.
type tsFinder struct {
	spans []funcSpan
	err   error
}

// tsNotFunction — идентификаторы, после которых `(` — конструкция языка, а не
// объявление функции. Объявить функцию с таким именем нельзя.
var tsNotFunction = map[string]bool{
	"if": true, "for": true, "while": true, "switch": true, "catch": true,
	"return": true, "function": true, "do": true, "else": true, "with": true,
	"typeof": true, "new": true, "delete": true, "void": true, "in": true,
	"of": true, "case": true, "await": true, "yield": true, "import": true,
	"export": true, "throw": true,
}

// find — функция по имени и (необязательному) владельцу.
func (f *tsFinder) find(name, owner string) (funcSpan, error) {
	if f.err != nil {
		return funcSpan{}, f.err
	}
	var hits []funcSpan
	for _, sp := range f.spans {
		if sp.Name == name && (owner == "" || sp.Owner == owner) {
			hits = append(hits, sp)
		}
	}
	if len(hits) == 1 {
		return hits[0], nil
	}
	if len(hits) > 1 {
		return funcSpan{}, fmt.Errorf("функций %s найдено %d (%s) — уточни receiver или переименуй",
			quoteFunc(name, owner), len(hits), strings.Join(ownerNames(hits), ", "))
	}
	return funcSpan{}, notFoundError(name, owner, f.names())
}

func (f *tsFinder) names() []string {
	out := make([]string, 0, len(f.spans))
	for _, sp := range f.spans {
		out = append(out, sp.Name)
	}
	return out
}

// tsClass — открытый класс: имя и позиция сразу за его телом.
type tsClass struct {
	name   string
	closer int
}

// scanTS — обход TS/JS-исходника и сбор границ всех функций.
func scanTS(src string) ([]funcSpan, error) {
	s := &tsScanner{src: src}
	var spans []funcSpan
	var classes []tsClass

	for !s.eof() {
		s.skipSpace()
		if s.eof() {
			break
		}
		if c := s.peek(); c == '"' || c == '\'' || c == '`' {
			if err := s.skipString(); err != nil {
				return nil, err
			}
			continue
		}
		if s.peekIs("/") && (s.peekAt(1) == '/' || s.peekAt(1) == '*') {
			s.skipComment()
			continue
		}

		if s.peekIs("class") && !isIdentPart(s.peekAt(len("class"))) {
			name, closer, err := s.readClass()
			if err != nil {
				return nil, err
			}
			classes = append(classes, tsClass{name: name, closer: closer})
			continue
		}

		if !isIdentStart(s.peek()) {
			s.i++
			continue
		}
		nameStart := s.i
		name := s.readIdent()
		if tsNotFunction[name] {
			continue
		}
		owner := enclosingClass(classes, nameStart)
		sp, ok := s.readSignatureBody(name, nameStart, owner)
		if ok {
			spans = append(spans, sp)
			s.i = sp.End
		}
	}
	return spans, nil
}

// enclosingClass — ближайший класс, тело которого ещё не закончилось на позиции
// pos. Анонимные объявления (типы, литералы) владельца не дают: иначе сигнатура
// анонимной функции внутри метода приписывалась бы классу, которого там нет.
func enclosingClass(classes []tsClass, pos int) string {
	for i := len(classes) - 1; i >= 0; i-- {
		if pos < classes[i].closer {
			return classes[i].name
		}
	}
	return ""
}

// readSignatureBody — после уже прочитанного имени читает сигнатуру и тело.
// Обрабатывает объявления `name(...)`, методы, поля-стрелки `name = (...) =>`
// и `name: (...) =>`.
func (s *tsScanner) readSignatureBody(name string, nameStart int, owner string) (funcSpan, bool) {
	save := s.i
	s.skipSpace()

	// Стрелочное присваивание: `name = ...` / `name: (...) =>`.
	if s.peek() == '=' || (s.peek() == ':' && s.arrowFollows()) {
		s.i++
		s.skipSpace()
		for _, kw := range []string{"async", "function"} {
			if s.peekIs(kw) && !isIdentPart(s.peekAt(len(kw))) {
				s.i += len(kw)
				s.skipSpace()
			}
		}
		if sp, ok := s.readBody(name, nameStart, owner); ok {
			return sp, true
		}
		s.i = save
		return funcSpan{}, false
	}

	// Сигнатура с параметрами: `name(...) {` — функция, метод, getter.
	if s.peek() == '(' {
		if _, _, err := s.matchPair('(', ')'); err != nil {
			s.i = save
			return funcSpan{}, false
		}
		s.skipSpace()
		// Тип возврата TS: до `{` или `=>`.
		if s.peek() == ':' {
			for !s.eof() && s.peek() != '{' && !s.peekIs("=>") && s.peek() != ';' {
				s.i++
			}
			s.skipSpace()
		}
		if sp, ok := s.readBody(name, nameStart, owner); ok {
			return sp, true
		}
	}
	s.i = save
	return funcSpan{}, false
}

// arrowFollows — после `:` действительно идёт стрелка (тип свойства), а не
// объектный литерал или `case x:`.
func (s *tsScanner) arrowFollows() bool {
	rest := s.src[s.i+1:]
	trimmed := strings.TrimLeft(rest, " \t\r\n")
	return strings.HasPrefix(trimmed, "(") || strings.HasPrefix(trimmed, "async") ||
		strings.HasPrefix(trimmed, "function")
}

// readBody — читает тело: `{...}` либо одно-выражное тело стрелки.
func (s *tsScanner) readBody(name string, nameStart int, owner string) (funcSpan, bool) {
	if s.peekIs("=>") {
		s.i += 2
		s.skipSpace()
		if s.peek() == '{' {
			end, err := s.matchBraceBlock()
			if err != nil {
				return funcSpan{}, false
			}
			return s.spanOf(name, nameStart, end, owner), true
		}
		// Одно-выражное тело: до `;`/`,`/переноса строки на нулевой глубине.
		start := s.i
		for !s.eof() {
			c := s.peek()
			if c == '{' || c == '(' || c == '[' {
				if _, _, err := s.matchPair(c, s.closerFor(c)); err != nil {
					return funcSpan{}, false
				}
				continue
			}
			if c == ';' || c == ',' || c == '}' || c == '\n' {
				break
			}
			s.i++
		}
		end := s.trimTrailingSpace(s.i)
		if end <= start {
			return funcSpan{}, false
		}
		s.i = end
		return s.spanOf(name, nameStart, end, owner), true
	}
	if s.peek() == '{' {
		end, err := s.matchBraceBlock()
		if err != nil {
			return funcSpan{}, false
		}
		return s.spanOf(name, nameStart, end, owner), true
	}
	return funcSpan{}, false
}

// readClass — читает `class Name ... {` и возвращает имя и позицию за `}`.
func (s *tsScanner) readClass() (string, int, error) {
	s.i += len("class")
	s.skipSpace()
	name := ""
	if isIdentStart(s.peek()) {
		name = s.readIdent()
	}
	for !s.eof() && s.peek() != '{' {
		s.i++
	}
	if s.eof() {
		return "", 0, fmt.Errorf("не найдено тело класса %q", name)
	}
	end, err := s.matchBraceBlock()
	if err != nil {
		return "", 0, err
	}
	return name, end, nil
}

// spanOf — границы объявления с поправкой на декораторы над ним.
func (s *tsScanner) spanOf(name string, nameStart, end int, owner string) funcSpan {
	start := s.decoratorStart(nameStart)
	return funcSpan{
		Name:  name,
		Start: start,
		End:   end,
		Owner: owner,
		Line:  strings.Count(s.src[:start], "\n") + 1,
	}
}

// decoratorStart — расширяет начало объявления вверх на строки-декораторы
// (@Component({...}), @Override): иначе декоратор остался бы над чужой функцией.
func (s *tsScanner) decoratorStart(nameStart int) int {
	for nameStart > 0 {
		lineStart := strings.LastIndex(s.src[:nameStart], "\n") + 1
		if lineStart == 0 {
			return nameStart
		}
		line := strings.TrimSpace(s.src[lineStart:nameStart])
		if !strings.HasPrefix(line, "@") {
			return nameStart
		}
		nameStart = lineStart
	}
	return nameStart
}

func (s *tsScanner) trimTrailingSpace(i int) int {
	for i > 0 {
		c := s.src[i-1]
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			i--
			continue
		}
		break
	}
	return i
}

// tsScanner — обход TS/JS с пропуском литералов.
type tsScanner struct {
	src string
	i   int
}

func (s *tsScanner) eof() bool { return s.i >= len(s.src) }

func (s *tsScanner) peek() byte {
	if s.eof() {
		return 0
	}
	return s.src[s.i]
}

func (s *tsScanner) peekAt(off int) byte {
	if s.i+off >= len(s.src) || s.i+off < 0 {
		return 0
	}
	return s.src[s.i+off]
}

func (s *tsScanner) peekIs(tok string) bool { return strings.HasPrefix(s.src[s.i:], tok) }

func (s *tsScanner) readIdent() string {
	start := s.i
	for !s.eof() && isIdentPart(s.peek()) {
		s.i++
	}
	return s.src[start:s.i]
}

func (s *tsScanner) closerFor(open byte) byte {
	switch open {
	case '(':
		return ')'
	case '[':
		return ']'
	case '{':
		return '}'
	}
	return 0
}

// skipSpace — пробелы, переводы строк и комментарии.
func (s *tsScanner) skipSpace() {
	for !s.eof() {
		c := s.peek()
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			s.i++
		case c == '/' && s.peekAt(1) == '/':
			s.skipComment()
		case c == '/' && s.peekAt(1) == '*':
			s.skipComment()
		default:
			return
		}
	}
}

// matchPair — парная скобка с учётом вложенных литералов и комментариев.
// Возвращает границы пары [Start, End).
func (s *tsScanner) matchPair(open, close byte) (int, int, error) {
	start := s.i
	depth := 0
	for !s.eof() {
		c := s.peek()
		switch {
		case c == '"' || c == '\'' || c == '`':
			if err := s.skipString(); err != nil {
				return 0, 0, err
			}
			continue
		case c == '/' && (s.peekAt(1) == '/' || s.peekAt(1) == '*'):
			s.skipComment()
			continue
		case c == '/' && s.regexAllowedHere():
			if err := s.skipRegex(); err != nil {
				return 0, 0, err
			}
			continue
		case c == open:
			depth++
		case c == close:
			depth--
			if depth == 0 {
				return start, s.i + 1, nil
			}
		}
		s.i++
	}
	return 0, 0, fmt.Errorf("не найдена парная %q начиная с позиции %d", string(close), start)
}

func (s *tsScanner) matchBraceBlock() (int, error) {
	_, end, err := s.matchPair('{', '}')
	return end, err
}

// tsRegexAllowedAfter — значимые токены, после которых `/` открывает регулярное
// выражение (классическое правило лексера JS).
var tsRegexAllowedAfter = map[string]bool{
	"return": true, "typeof": true, "case": true, "in": true, "of": true,
	"new": true, "delete": true, "void": true, "instanceof": true,
	"do": true, "else": true, "yield": true, "await": true, "throw": true,
}

var tsRegexAllowedPunct = map[byte]bool{
	'(': true, ',': true, '=': true, ':': true, '[': true, '!': true,
	'&': true, '|': true, '?': true, '{': true, '}': true, ';': true,
	'+': true, '-': true, '*': true, '%': true, '<': true, '>': true, '~': true,
}

// regexAllowedHere — открывает ли текущий `/` регулярный литерал. Решение по
// ПРЕДЫДУЩЕМУ значимому токену: смотрим назад от позиции, пропуская пробелы и
// комментарии, поэтому состояние сканера не может «протухнуть».
func (s *tsScanner) regexAllowedHere() bool {
	i := s.i - 1
	for i >= 0 {
		c := s.src[i]
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			i--
			continue
		}
		if isIdentPart(c) {
			start := i
			for i >= 0 && isIdentPart(s.src[i]) {
				i--
			}
			return tsRegexAllowedAfter[s.src[i+1:start+1]]
		}
		return tsRegexAllowedPunct[c]
	}
	// Начало файла: литерал допустим.
	return true
}

// skipString — строковый литерал, включая шаблонные строки с вложенными
// интерполяциями `${...}`.
func (s *tsScanner) skipString() error {
	quote := s.peek()
	s.i++
	if quote == '`' {
		depth := 0
		for !s.eof() {
			c := s.peek()
			switch {
			case c == '\\':
				s.i += 2
				continue
			case depth == 0 && c == '`':
				s.i++
				return nil
			case depth == 0 && c == '$' && s.peekAt(1) == '{':
				depth++
				s.i += 2
				continue
			case depth > 0 && c == '`':
				if err := s.skipString(); err != nil {
					return err
				}
				continue
			case depth > 0 && c == '{':
				depth++
			case depth > 0 && c == '}':
				depth--
			}
			s.i++
		}
		return fmt.Errorf("незакрытая шаблонная строка")
	}
	for !s.eof() {
		c := s.peek()
		if c == '\\' {
			s.i += 2
			continue
		}
		if c == quote {
			s.i++
			return nil
		}
		if c == '\n' {
			return fmt.Errorf("незакрытая строковая константа")
		}
		s.i++
	}
	return fmt.Errorf("незакрытая строковая константа")
}

// skipRegex — регулярный литерал с классами символов и экранированием.
func (s *tsScanner) skipRegex() error {
	s.i++
	inClass := false
	for !s.eof() {
		c := s.peek()
		switch {
		case c == '\\':
			s.i += 2
			continue
		case c == '[':
			inClass = true
		case c == ']':
			inClass = false
		case c == '/' && !inClass:
			s.i++
			for !s.eof() && isIdentPart(s.peek()) {
				s.i++
			}
			return nil
		case c == '\n':
			return fmt.Errorf("незакрытый регулярный литерал")
		}
		s.i++
	}
	return fmt.Errorf("незакрытый регулярный литерал")
}

func (s *tsScanner) skipComment() {
	if s.peekAt(1) == '/' {
		for !s.eof() && s.peek() != '\n' {
			s.i++
		}
		return
	}
	s.i += 2
	for !s.eof() && !(s.peek() == '*' && s.peekAt(1) == '/') {
		s.i++
	}
	if !s.eof() {
		s.i += 2
	}
}

func isIdentStart(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

// pyFinder — поиск функций в Python по отступам.
type pyFinder struct {
	spans []funcSpan
}

// pyLine — строка с отступом и границами.
type pyLine struct {
	start int
	end   int
	text  string
	indent int
	blank bool
}

func (f *pyFinder) find(name, owner string) (funcSpan, error) {
	var hits []funcSpan
	for _, sp := range f.spans {
		if sp.Name == name && (owner == "" || sp.Owner == owner) {
			hits = append(hits, sp)
		}
	}
	if len(hits) == 1 {
		return hits[0], nil
	}
	if len(hits) > 1 {
		return funcSpan{}, fmt.Errorf("функций %s найдено %d (%s) — уточни receiver или переименуй",
			quoteFunc(name, owner), len(hits), strings.Join(ownerNames(hits), ", "))
	}
	return funcSpan{}, notFoundError(name, owner, f.names())
}

func (f *pyFinder) names() []string {
	out := make([]string, 0, len(f.spans))
	for _, sp := range f.spans {
		out = append(out, sp.Name)
	}
	return out
}

// scanPy — обход Python по отступам. Границы функции: от строки `def` (или
// декораторов над ней) до первой непустой строки с отступом <= отступа `def`.
// Так тело не может «съесть» соседний код, а хвостовые пустые строки в замену
// не попадают.
func scanPy(src string) ([]funcSpan, error) {
	lines := splitPyLines(src)
	var spans []funcSpan
	// Классы-владельцы: отступ класса и позиция конца тела.
	type pyClass struct {
		name   string
		indent int
		end    int
	}
	var classes []pyClass

	for idx := 0; idx < len(lines); idx++ {
		ln := lines[idx]
		if ln.blank {
			continue
		}
		trimmed := strings.TrimSpace(ln.text)
		kind, name, ok := pyDeclKind(trimmed)
		if !ok {
			continue
		}
		// Конец тела — первая непустая строка с отступом <= отступа объявления.
		end := len(src)
		for j := idx + 1; j < len(lines); j++ {
			next := lines[j]
			if next.blank {
				continue
			}
			if next.indent <= ln.indent {
				end = next.start
				break
			}
		}
		if end == len(src) {
			// Тело до конца файла: обрезаем хвостовые пустые строки.
			end = trimEndWS(src, end)
		} else {
			// Хвостовые пустые строки перед следующим объявлением — не часть
			// функции: заканчиваем на последней непустой строке тела.
			for j := idx + 1; j < len(lines); j++ {
				if lines[j].start >= end {
					break
				}
				if !lines[j].blank {
					end = lines[j].end
				}
			}
		}
		start := ln.start
		// Декораторы над объявлением входят в границы.
		for idx-startIdx := idx; startIdx := 0; idx > 0; {
			break
		}
		for k := idx - 1; k >= 0; k-- {
			if lines[k].blank {
				continue
			}
			if strings.HasPrefix(strings.TrimSpace(lines[k].text), "@") && lines[k].indent == ln.indent {
				start = lines[k].start
				continue
			}
			break
		}
		owner := ""
		for i := len(classes) - 1; i >= 0; i-- {
			if classes[i].indent < ln.indent && start < classes[i].end {
				owner = classes[i].name
				break
			}
		}
		if kind == "class" {
			classes = append(classes, pyClass{name: name, indent: ln.indent, end: end})
			continue
		}
		spans = append(spans, funcSpan{
			Name:  name,
			Start: start,
			End:   end,
			Owner: owner,
			Line:  strings.Count(src[:start], "\n") + 1,
		})
	}
	return spans, nil
}

// pyDeclKind — вид объявления в строке: "def" или "class".
func pyDeclKind(trimmed string) (kind, name string, ok bool) {
	rest := trimmed
	if strings.HasPrefix(rest, "async ") {
		rest = strings.TrimSpace(strings.TrimPrefix(rest, "async "))
	}
	for _, kw := range []string{"def ", "class "} {
		if strings.HasPrefix(rest, kw) {
			rest = strings.TrimSpace(rest[len(kw):])
			name = pyDeclName(rest)
			if name == "" {
				return "", "", false
			}
			return strings.TrimSpace(kw), name, true
		}
	}
	return "", "", false
}

// pyDeclName — имя из заголовка объявления: до `(` или `:`.
func pyDeclName(rest string) string {
	end := len(rest)
	if i := strings.IndexByte(rest, '('); i >= 0 && i < end {
		end = i
	}
	if i := strings.IndexByte(rest, ':'); i >= 0 && i < end {
		end = i
	}
	name := strings.TrimSpace(rest[:end])
	if name == "" || !isPyIdent(name) {
		return ""
	}
	return name
}

func isPyIdent(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (i > 0 && c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return len(s) > 0
}

// splitPyLines — строки с отступом и границами. Табы считаем за ширину 1: у
// смешанных отступов Python всё равно не запустится, а наш подсчёт не должен
// молча расходиться с интерпретатором.
func splitPyLines(src string) []pyLine {
	var out []pyLine
	start := 0
	for i := 0; i <= len(src); i++ {
		if i == len(src) || src[i] == '\n' {
			text := src[start:i]
			trimmed := strings.TrimLeft(text, " \t")
			out = append(out, pyLine{
				start:  start,
				end:    i,
				text:   text,
				indent: len(text) - len(trimmed),
				blank:  strings.TrimSpace(text) == "",
			})
			start = i + 1
		}
	}
	// Хвостовой пустой элемент после последнего перевода строки не нужен.
	if n := len(out); n > 0 && out[n-1].text == "" {
		out = out[:n-1]
	}
	return out
}

func trimEndWS(src string, end int) int {
	for end > 0 {
		c := src[end-1]
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			end--
			continue
		}
		break
	}
	return end
}

// notFoundError — сообщение с перечнем найденных функций: по нему модель сразу
// видит опечатку в имени или receiver.
func notFoundError(name, owner string, have []string) error {
	msg := fmt.Sprintf("функция %q не найдена", name)
	if owner != "" {
		msg += " у владельца " + quoteFunc(owner, "")
	}
	if len(have) > 0 {
		msg += "; найдены: " + strings.Join(have, ", ")
	}
	return fmt.Errorf("%s", msg)
}

func quoteFunc(name, owner string) string {
	if owner != "" {
		return owner + "." + name
	}
	return name
}

func ownerNames(spans []funcSpan) string {
	out := make([]string, 0, len(spans))
	for _, sp := range spans {
		if sp.Owner != "" {
			out = append(out, sp.Owner+"."+sp.Name)
			continue
		}
		out = append(out, sp.Name)
	}
	return out
}

